return [ 'project-id-version' => 'fluid-checkout','mime-version' => '1.0','content-type' => 'text/plain; charset=utf-8','content-transfer-encoding' => '8bit','language-team' => 'Fluid Checkout','last-translator' => 'Fluid Checkout','pot-creation-date' => '2025-03-05 23:46+0000','report-msgid-bugs-to' => 'https://fluidcheckout.com/support','x-poedit-basepath' => '..','x-poedit-keywordslist' => '__;_e;_ex:1,2c;_n:1,2;_n_noop:1,2;_nx:1,2,4c;_nx_noop:1,2,3c;_x:1,2c;esc_attr__;esc_attr_e;esc_attr_x:1,2c;esc_html__;esc_html_e;esc_html_x:1,2c','x-poedit-searchpath-0' => '.','x-poedit-searchpathexcluded-0' => '*.js','x-poedit-sourcecharset' => 'UTF-8','plural-forms' => 'nplurals=2; plural=(n != 1);','messages' => ['WooCommerce' => 'WooCommerce','Go to Plugin Search' => 'Գնացեք Plugin Search','Activate %s' => 'Ակտիվացրեք %s-ը','<strong>%1$s</strong> requires <strong>%2$s</strong> to be installed and activated. <a href="%4$s">%3$s</a>' => '<strong>%1$s-ի համար</strong> անհրաժեշտ է <strong>%2$s-ի</strong> տեղադրումը և ակտիվացումը: <a href="%4$s">%3$s</a>','Enter your code here' => 'Մուտքագրեք ձեր կոդը այստեղ','Add %s' => 'Ավելացնել %s','Remove' => 'Հեռացնել','Order number and receipt will be sent to this email address.' => 'Պատվերի համարը և անդորրագիրը կուղարկվեն այս էլ.','Apartment, unit, building, floor, etc.' => 'Բնակարան, միավոր, շենք, հարկ և այլն:','Shipping phone' => 'Առաքման հեռախոս','Only used for shipping-related questions.' => 'Օգտագործվում է միայն առաքման հետ կապված հարցերի համար:','Single step' => 'Մեկ քայլ','Click to go to the order summary' => 'Սեղմեք՝ պատվերի ամփոփագրին անցնելու համար','Cart total:' => 'Զամբյուղի ընդհանուրը.','Proceed to %s' => 'Անցեք %s','Proceed to contact' => 'Շարունակեք կապ հաստատել','Proceed to shipping' => 'Անցեք առաքմանը','Proceed to billing' => 'Անցեք վճարման','Proceed to payment' => 'Անցեք վճարմանը','Shipping method' => 'Առաքման եղանակը','Additional notes' => 'Լրացուցիչ նշումներ','Payment method' => 'Վճարման եղանակ','Step %1$s of %2$s' => 'Քայլ %1$s %2$s-ից','Change: %s' => 'Փոփոխություն՝ %s','Not selected yet.' => 'Դեռ ընտրված չէ:','Same as shipping address' => 'Նույնը, ինչ առաքման հասցեն','Same as billing address' => 'Նույնը, ինչ վճարման հասցեն','Order summary' => 'Պատվերի ամփոփագիր','Edit cart' => 'Խմբագրել զամբյուղը','Did you mean %s?' => 'Նկատի ունեիք %s:','Change email address to: {suggestion-value}' => 'Փոփոխել էլփոստի հասցեն՝ {suggestion-value}','This is a required field.' => 'Սա պարտադիր դաշտ է:','This is not a valid email address.' => 'Սա վավեր էլփոստի հասցե չէ:','This field does not match the related field value.' => 'Այս դաշտը չի համապատասխանում համապատասխան դաշտի արժեքին:','The CPF number "{cpf_number}" is invalid.' => '«{cpf_number}» CPF համարն անվավեր է:','The CNPJ number "{cnpj_number}" is invalid.' => 'CNPJ «{cnpj_number}» համարն անվավեր է:','(Required)' => '(պարտադիր)','Checkout Header - Desktop' => 'Checkout Header - Desktop','Display widgets on the checkout header for large screens. Only displayed if using the plugin\'s checkout header.' => 'Ցուցադրել վիդջեթները վճարման վերնագրում մեծ էկրանների համար: Ցուցադրվում է միայն այն դեպքում, եթե օգտագործում եք հավելվածի վճարման վերնագիրը:','Checkout Header - Mobile' => 'Checkout Header - Բջջային','Display widgets below the checkout header for mobile devices. Only displayed if using the plugin\'s checkout header.' => 'Ցուցադրել վիջեթները շարժական սարքերի համար վճարման վերնագրի տակ: Ցուցադրվում է միայն հավելվածի վճարման վերնագիրն օգտագործելու դեպքում:','Checkout Sidebar' => 'Ստուգեք կողագոտին','Display widgets on the checkout sidebar after the order summary.' => 'Ցուցադրեք վիջեթները վճարման կողագոտում պատվերի ամփոփումից հետո:','Checkout Order Summary' => 'Ստուգման պատվերի ամփոփում','Display widgets inside the order summary at the checkout page.' => 'Ցուցադրել վիդջեթները պատվերի ամփոփագրի ներսում վճարման էջում:','Checkout Below Place Order' => 'Ստուգեք ներքևում Տեղադրեք պատվերը','Display widgets below the place order button at the checkout page.' => 'Ցուցադրեք վիջեթները՝ տեղաբաշխման կոճակի տակ՝ վճարման էջում:','Checkout Footer' => 'Ստուգման ստորագիր','Display widgets on the checkout footer. Only displayed if using the plugin\'s checkout footer.' => 'Ցուցադրել վիդջեթները վճարման էջատակի վրա: Ցուցադրվում է միայն այն դեպքում, եթե օգտագործում եք հավելվածի վճարման էջատակը:','Classic' => 'Դասական','Boxed' => 'Բռնկված','Split' => 'Պառակտում','Minimalist' => 'Մինիմալիստական','Fluid Checkout and Delivery Date plugins by CodeRockz' => 'Fluid Checkout և Delivery Date plugins CodeRockz-ի կողմից','<p>We detected that you are using the plugins Delivery & Pickup Date Time for WooCommerce (free and PRO) by CodeRockz. Integration with these plugins have been moved to Fluid Checkout PRO.</p>' => '<p>Մենք հայտնաբերեցինք, որ դուք օգտագործում եք «CodeRockz»-ի կողմից WooCommerce-ի (անվճար և PRO) «Առաքման և ընդունման ամսաթիվը» հավելվածները: Այս պլագինների հետ ինտեգրումը տեղափոխվել է Fluid Checkout PRO:</p>','Upgrade to PRO' => 'Թարմացրեք PRO-ի','Fluid Checkout database updated successfully' => 'Fluid Checkout տվյալների բազան հաջողությամբ թարմացվել է','The database changes where applied successfully.' => 'Տվյալների բազան փոխվում է, որտեղ հաջողությամբ կիրառվում է:','Dismiss' => 'Հեռացնել','Fluid Checkout database update' => 'Fluid Checkout տվյալների բազայի թարմացում','Some changes to the database are required. As with any update, we recommend you to <strong>take a full backup of your website before proceeding</strong>.' => 'Տվյալների բազայում որոշակի փոփոխություններ են պահանջվում: Ինչպես ցանկացած թարմացում, մենք խորհուրդ ենք տալիս <strong>շարունակել ձեր կայքի ամբողջական կրկնօրինակը</strong> :','Update database' => 'Թարմացրեք տվյալների բազան','Fluid Checkout is not compatible with the Divi Builder checkout layout' => 'Fluid Checkout-ը համատեղելի չէ Divi Builder վճարման դասավորության հետ','<p>Fluid Checkout needs the classic WooCommerce shortcode-based checkout form to work. When using the Divi Builder to customize the look and feel of the checkout page, the classic shortcodes are replaced with custom widgets from the Divi Builder for each part of the checkout page. These custom widgets are not compatible with Fluid Checkout.</p><p>Please edit your checkout page replacing the Divi Builder widgets with the a text widget containing the shortcode <code>[woocommerce_checkout]</code>.</p>' => '<p>Fluid Checkout-ին անհրաժեշտ է WooCommerce-ի դասական կարճ կոդերի վրա հիմնված վճարման ձևը, որպեսզի աշխատի: Երբ Divi Builder-ն օգտագործում եք վճարման էջի տեսքն ու զգացողությունը հարմարեցնելու համար, դասական կարճ կոդերը փոխարինվում են Divi Builder-ի հատուկ վիդջեթներով վճարման էջի յուրաքանչյուր մասի համար: Այս հատուկ վիջեթները համատեղելի չեն Fluid Checkout-ի հետ:</p><p> Խնդրում ենք խմբագրել ձեր վճարման էջը՝ փոխարինելով Divi Builder վիջեթները տեքստային վիջեթով, որը պարունակում է կարճ կոդը <code>[woocommerce_checkout]</code> :</p>','Edit the checkout page' => 'Խմբագրել վճարման էջը','Read the documentation.' => 'Կարդացեք փաստաթղթերը.','Germanized PRO multistep checkout feature needs to be disabled when using Fluid Checkout' => 'Գերմանականացված PRO բազմաքայլ վճարման գործառույթն անհրաժեշտ է անջատել Fluid Checkout-ն օգտագործելիս','When using Fluid Checkout, the multistep feature from the Germanized PRO plugin becomes unnecessary and can cause <strong>critical errors while processing new orders</strong>. Please disable the Germanized PRO multistep checkout feature in the plugin settings.' => 'Fluid Checkout-ն օգտագործելիս գերմանացված PRO հավելվածի բազմաքայլ գործառույթն ավելորդ է դառնում և կարող է առաջացնել <strong>կրիտիկական սխալներ նոր պատվերներ մշակելիս</strong> : Խնդրում ենք անջատել գերմանացված PRO բազմաքայլ վճարման գործառույթը հավելվածի կարգավորումներում:','Go to Germanized settings' => 'Գնացեք գերմանացված կարգավորումներ','Thanks for choosing Fluid Checkout!' => 'Շնորհակալություն Fluid Checkout-ն ընտրելու համար:','You have been using the plugin for a while now. How do you like it so far? <br>Please give us a quick rating, we appreciate every bit of feedback and it encourages us to keep improving the plugin :)' => 'Դուք արդեն որոշ ժամանակ օգտագործում եք հավելվածը: Ինչպե՞ս է դա ձեզ դուր գալիս մինչ այժմ:<br> Խնդրում ենք մեզ արագ գնահատական տալ, մենք գնահատում ենք յուրաքանչյուր արձագանք և դա մեզ խրախուսում է շարունակել կատարելագործել հավելվածը :)','Rate the plugin' => 'Գնահատեք plugin-ը','I need help!' => 'Ես օգնության կարիք ունեմ։','Some features of WooCommerce Checkout Manager by Quadlayers might not work as expected when using it with Fluid Checkout. Read <a href="%s">our documentation</a> for more information and alternative solutions.' => 'WooCommerce Checkout Manager-ի Quadlayers-ի որոշ գործառույթներ կարող են չաշխատել այնպես, ինչպես սպասվում էր, երբ այն օգտագործում եք Fluid Checkout-ով: Լրացուցիչ տեղեկությունների և այլընտրանքային լուծումների համար կարդացեք <a href="%s">մեր փաստաթղթերը</a> :','Read documentation' => 'Կարդացեք փաստաթղթերը','Don\'t show this again' => 'Սա այլևս մի ցուցադրեք','Fluid Checkout PRO' => 'Fluid Checkout PRO','More design templates' => 'Դիզայնի ավելի շատ կաղապարներ','Optimized cart page' => 'Օպտիմիզացված զամբյուղի էջ','Optimized order received / thank you page' => 'Օպտիմիզացված պատվեր ստացված / շնորհակալություն էջ','Edit cart contents at checkout page' => 'Խմբագրել զամբյուղի բովանդակությունը վճարման էջում','Account matching / user matching' => 'Հաշվի համընկնում / օգտվողի համապատասխանություն','Trust symbols on the cart and thank you pages' => 'Վստահության խորհրդանիշները զամբյուղի և շնորհակալական էջերի վրա','More positions for the coupon code on the checkout page' => 'Կտրոնի կոդի ավելի շատ դիրքեր վճարման էջում','International phone numbers' => 'Միջազգային հեռախոսահամարներ','Gift messages and packing slips' => 'Նվերների հաղորդագրություններ և փաթեթավորման թերթիկներ','Local pickup and in-store collection' => 'Տեղական պիկապ և խանութի հավաքածու','EU-VAT Assistant' => 'ԵՄ ԱԱՀ-ի օգնական','I already have it – Hide this offer' => 'Ես արդեն ունեմ այն – Թաքցնել այս առաջարկը','Activated' => 'Ակտիվացված է','Address book' => 'Հասցեների գիրք','Select an image' => 'Ընտրեք պատկեր','Cart layout' => 'Զամբյուղի դասավորությունը','Cart optimizations' => 'Զամբյուղի օպտիմալացում','Enable cart page optimizations' => 'Միացնել զամբյուղի էջի օպտիմալացումը','Header and footer template' => 'Վերնագրի և ստորագրի ձևանմուշ','Controls whether to use the distraction free page header and footer or keep the currently active theme\'s header and footer.' => 'Վերահսկում է՝ օգտագործե՞լ ուշադրությունը շեղող էջի վերնագիրն ու էջատակը, թե՞ պահել ներկայիս ակտիվ թեմայի վերնագիրն ու էջատակը:','Distraction free header and footer' => 'Շեղումից զերծ վերնագիր և ստորագիր','Theme\'s header and footer' => 'Թեմայի վերնագիր և ստորագիր','Cart elements' => 'Զամբյուղի տարրեր','Make the order summary stay visible on the cart page while scrolling' => 'Պատվերի ամփոփագիրը տեսանելի դարձրեք զամբյուղի էջում ոլորելիս','Coupon codes' => 'Կտրոնների կոդերը','Hidden' => 'Թաքնված','Before the cart items section' => 'Նախքան զամբյուղի իրերի բաժինը','Inside the cart items section' => 'Զամբյուղի իրերի բաժնի ներսում','After the cart items section' => 'Զամբյուղի իրերի բաժնից հետո','Before the shipping section' => 'Մինչև առաքման բաժինը','After the shipping section' => 'Առաքման բաժնից հետո','Before the order summary' => 'Նախքան պատվերի ամփոփումը','Inside the order summary' => 'Պատվերի ամփոփում','Before the order totals' => 'Մինչև պատվերի գումարը','After the order totals' => 'Պատվերի գումարից հետո','After the order summary' => 'Պատվերի ամփոփումից հետո','Shipping' => 'Առաքում','Select position where to display the shipping costs and calculator on the cart page.' => 'Ընտրեք դիրքը, որտեղ ցուցադրվելու են առաքման ծախսերը և հաշվիչը զամբյուղի էջում:','Display as a cart section' => 'Ցուցադրել որպես զամբյուղի բաժին','Cross-sells' => 'Խաչաձև վաճառք','Select position where to display the cross-sells section on the cart page.' => 'Ընտրեք դիրքը, որտեղ կցուցադրվի խաչաձև վաճառքի բաժինը զամբյուղի էջում:','Before the cart actions' => 'Նախքան սայլի գործողությունները','After the cart actions' => 'Սայլի գործողություններից հետո','Layout of cross-sell items on the cart page.' => 'Խաչաձեւ վաճառքի ապրանքների դասավորությունը զամբյուղի էջում:','Optimized horizontal cross-sells layout' => 'Օպտիմիզացված հորիզոնական խաչաձև վաճառքի դասավորություն','Theme\'s cross-sells layout' => 'Թեմայի խաչաձև վաճառքի դասավորությունը','Number of cross-sell items to display on the cart page' => 'Զամբյուղի էջում ցուցադրվող խաչաձև վաճառքի ապրանքների քանակը','Add widget areas to the cart page' => 'Ավելացնել վիդջեթների տարածքներ զամբյուղի էջում','These widget areas are used to add trust symbols and trust badges on the cart page.' => 'Այս վիդջեթների տարածքներն օգտագործվում են զամբյուղի էջում վստահության նշաններ և վստահության նշաններ ավելացնելու համար:','Checkout' => 'Ստուգում','Checkout layout' => 'Ստուգման դասավորությունը','Design template' => 'Դիզայնի ձևանմուշ','Dark mode' => 'Մութ ռեժիմ','Enable dark mode' => 'Միացնել մութ ռեժիմը','Logo image' => 'Լոգոյի պատկեր','Choose an image to be displayed on the checkout page header. Only applies when using the distraction free header and footer.' => 'Ընտրեք պատկեր, որը կցուցադրվի վճարման էջի վերնագրում: Կիրառվում է միայն ուշադրությունը շեղող առանց վերնագրի և ստորագրի օգտագործման դեպքում:','Header background color' => 'Վերնագրի ֆոնի գույնը','Choose a background color for the checkout page header. Only applies when using the distraction free header and footer.' => 'Ընտրեք ֆոնի գույնը վճարման էջի վերնագրի համար: Կիրառվում է միայն ուշադրությունը շեղող առանց վերնագրի և ստորագրի օգտագործման դեպքում:','HTML color value. ie: #f3f3f3' => 'HTML գույնի արժեքը. այսինքն՝ #f3f3f3','Page background color' => 'Էջի ֆոնի գույնը','Choose a background color for the checkout page. Color is applied to the <em>body</em> element.' => 'Ընտրեք ֆոնի գույնը վճարման էջի համար: Գույնը կիրառվում է <em>մարմնի</em> տարրի վրա:','Footer background color' => 'Ստորագրի ֆոնի գույնը','Choose a background color for the checkout page footer. Only applies when using the distraction free header and footer.' => 'Ընտրեք ֆոնի գույնը վճարման էջի ստորագրի համար: Կիրառվում է միայն ուշադրությունը շեղող առանց վերնագրի և ստորագրի օգտագործման դեպքում:','Progress bar' => 'Առաջընթացի բար','Display the checkout progress bar when using multi-step checkout layout' => 'Ցուցադրել վճարումների առաջընթացի գոտին, երբ օգտագործում եք վճարումների բազմաքայլ դասավորությունը','Make the checkout progress bar stay visible while scrolling' => 'Դարձրեք վճարումների առաջընթացի գոտին տեսանելի մնալ ոլորելիս','Express checkout' => 'Էքսպրես վճարում','Enable the express checkout section' => 'Միացնել էքսպրես վճարման բաժինը','Displays the express checkout section at checkout when supported payment gateways have this feature enabled.' => 'Ցուցադրում է էքսպրես վճարումների բաժինը վճարման ժամանակ, երբ աջակցվող վճարային դարպասներն ունեն այս գործառույթը միացված:','Display express checkout buttons in one line for larger screens' => 'Ցուցադրել էքսպրես վճարման կոճակները մեկ տողում՝ ավելի մեծ էկրանների համար','Ignore additional checkout required fields when paying with a compatible express checkout payment gateway' => 'Անտեսեք լրացուցիչ վճարումների պարտադիր դաշտերը, երբ վճարում եք համապատասխան էքսպրես վճարման դարպասով','Make the order summary stay visible while scrolling' => 'Պատվերի ամփոփագիրը տեսանելի դարձրեք ոլորելիս','Choose a background color for the order summary section.' => 'Ընտրեք ֆոնի գույնը պատվերի ամփոփման բաժնի համար:','Highlight the order totals row in the order summary table' => 'Պատվերների ամփոփ աղյուսակում ընդգծեք պատվերի գումարների տողը','Most useful when the order summary section does not have a highlighted background color. Might also apply to the Cart, Order Received and View Order pages when using Fluid Checkout PRO.' => 'Առավել օգտակար է, երբ պատվերի ամփոփման բաժինը չունի ընդգծված ֆոնի գույն: Կարող է կիրառվել նաև զամբյուղի, ստացված պատվերի և դիտելու պատվերի էջերը Fluid Checkout PRO-ի օգտագործման ժամանակ:','Action link on the order summary at checkout.' => 'Գործողությունների հղումը պատվերի ամփոփագրի վերաբերյալ վճարման ժամանակ:','Edit cart link' => 'Խմբագրել զամբյուղի հղումը','Cart items count' => 'Զամբյուղի իրերը հաշվում են','Link to shop page' => 'Հղում դեպի խանութի էջի','Cart items' => 'Զամբյուղի իրեր','Hide cart items errors at the checkout page' => 'Թաքցնել զամբյուղի ապրանքների սխալները վճարման էջում','Do not display the cart items errors message at the top of the checkout page. When submitting the checkout form to complete the purchase, these error messages will always be displayed.' => 'Մի ցուցադրեք զամբյուղի ապրանքների սխալների մասին հաղորդագրությունը վճարման էջի վերևում: Գնումը ավարտելու համար վճարման ձևը ներկայացնելիս այս սխալի հաղորդագրությունները միշտ կցուցադրվեն:','Place order' => 'Տեղադրել պատվեր','Define the position to display "Place order" and terms checkbox section.' => 'Սահմանեք «Տեղադրել պատվեր» և տերմինների վանդակի հատվածը ցուցադրելու դիրքը:','Some options might not be compatible with some plugins and themes.' => 'Որոշ ընտրանքներ կարող են համատեղելի չլինել որոշ պլագինների և թեմաների հետ:','Below the payment section' => 'Վճարման բաժնի տակ','Below the order summary' => 'Պատվերի ամփոփագրի տակ','Both below the payment section and the order summary' => 'Ե՛վ վճարման բաժնից, և՛ պատվերի ամփոփագրի տակ','Add widget areas to the checkout page' => 'Վիդջեթների տարածքներ ավելացրեք վճարման էջում','These widget areas are used to add trust symbols and trust badges on the checkout page.' => 'Այս վիդջեթների տարածքներն օգտագործվում են վճարման էջում վստահության նշաններ և վստահության նշաններ ավելացնելու համար:','Display the coupon codes section title' => 'Ցուցադրել կտրոնի կոդերի բաժնի անվանումը','Select position where to display the coupon codes section on the checkout page.' => 'Ընտրեք դիրքը, որտեղ կցուցադրվի կտրոնների կոդերի բաժինը վճարման էջում:','Before the checkout steps' => 'Նախքան վճարման քայլերը','As a substep before payment methods' => 'Որպես ենթակետ՝ վճարման եղանակներից առաջ','As a substep after payment methods' => 'Որպես ենթակետ վճարման եղանակներից հետո','Default button style' => 'Կոճակի կանխադրված ոճը','"Add" link button' => '«Ավելացնել» հղման կոճակը','Checkout fields' => 'Ստուգման դաշտեր','Optional fields' => 'Ընտրովի դաշտեր','Hide optional fields behind a link button' => 'Թաքցնել ընտրովի դաշտերը հղման կոճակի հետևում','It is recommended to keep this option checked to reduce the number of open input fields, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">read the research</a>.' => 'Խորհուրդ է տրվում ստուգված պահել այս տարբերակը՝ մուտքագրման բաց դաշտերի քանակը նվազեցնելու համար, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">կարդացեք հետազոտությունը</a> :','Do not hide "Address line 2" fields behind a link button' => 'Մի թաքցրեք «Հասցեի տող 2» դաշտերը հղման կոճակի հետևում','Recommended only when most customers actually need the "Address line 2" field, or when getting the right shipping address is crucial (ie. if delivering food and other perishable products).' => 'Առաջարկվում է միայն այն դեպքում, երբ հաճախորդների մեծամասնությանը իսկապես անհրաժեշտ է «Հասցեի տող 2» դաշտը, կամ երբ առաքման ճիշտ հասցե ստանալը կարևոր է (այսինքն՝ սննդամթերք և այլ փչացող ապրանքներ առաքելու դեպքում):','Billing address' => 'Վճարման հասցե','Select position where to display the billing address section on the checkout page.' => 'Ընտրեք այն դիրքը, որտեղ կցուցադրվի վճարման հասցեի բաժինը վճարման էջում:','As a step before shipping' => 'Որպես առաքումից առաջ քայլ','As a sub-step before the shipping address section' => 'Որպես ենթաքայլ մինչև առաքման հասցեի բաժինը','As a sub-step after the shipping address section' => 'Որպես ենթակետ՝ առաքման հասցեի բաժնից հետո','As a step after shipping' => 'Որպես քայլ առաքումից հետո','As a sub-step before the payment section' => 'Որպես ենթաքայլ մինչև վճարման բաժինը','Force billing and shipping addresses to the same (single section)' => 'Ստիպել վճարման և առաքման հասցեները նույնը (մեկ բաժին)','Checkbox for "Same as shipping/billing address" checked by default' => '«Նույնը, ինչ առաքման/վճարման հասցեն» վանդակը նշված է լռելյայն','The checkbox "Same as shiping address" will start as checked by default when the shipping address section is displayed first. <br>The checkbox "Same as billing address" will start as checked by default when the billing address section is displayed first. <br> It is recommended to leave this option checked as to significantly reduce the number of open input fields at checkout, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">read the research</a>.' => '«Նույնը, ինչ առաքման հասցեն» վանդակը կսկսվի որպես լռելյայն նշված, երբ առաջինը կցուցադրվի առաքման հասցեի բաժինը:<br> «Նույնը, ինչ վճարման հասցեն» վանդակը կսկսվի որպես լռելյայն նշված, երբ առաջինը ցուցադրվի վճարման հասցեի բաժինը:<br> Խորհուրդ է տրվում ստուգված թողնել այս տարբերակը, որպեսզի զգալիորեն կրճատվի մուտքագրման բաց դաշտերի քանակը վճարման ժամանակ, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">կարդացեք հետազոտությունը</a> :','Highlight the billing address section in the checkout form' => 'Նշեք վճարման հասցեի բաժինը վճարման ձևում','Shipping address' => 'Առաքման հասցե','Highlight the shipping address section in the checkout form' => 'Նշեք առաքման հասցեի բաժինը վճարման ձևում','Shipping methods' => 'Առաքման մեթոդներ','Choose in which position to display the shipping methods section.' => 'Ընտրեք, թե որ դիրքում կցուցադրվի առաքման մեթոդներ բաժինը:','Before shipping address' => 'Նախքան առաքման հասցեն','After shipping address' => 'Առաքումից հետո հասցեն','Local pickup' => 'Տեղական պիկապ','Removes shipping address section when a local pickup shipping method is selected.' => 'Հեռացնում է առաքման հասցեի բաժինը, երբ ընտրված է առաքման տեղական եղանակ:','Replaces the shipping address with the pickup point location when a local pickup shipping method is selected.' => 'Փոխարինում է առաքման հասցեն վերցնելու կետի գտնվելու վայրով, երբ ընտրվում է տեղային պիկապ առաքման եղանակը:','Choose which address to save as the shipping address for local pickup orders.' => 'Ընտրեք, թե որ հասցեն պետք է պահպանվի որպես տեղական պիկապ պատվերների առաքման հասցե:','Save the selected pickup location' => 'Պահպանեք ընտրված հավաքման վայրը','Save same as the billing address' => 'Պահպանեք նույնը, ինչ վճարման հասցեն','Do not save any shipping address' => 'Մի պահեք առաքման հասցե','Company name field for shipping address' => 'Ընկերության անվանման դաշտ առաքման հասցեի համար','Change visibility for the company name field for the shipping address section on the checkout form.' => 'Փոխեք ընկերության անվանման դաշտի տեսանելիությունը առաքման հասցեի բաժնի համար վճարման ձևի վրա:','If field is set as "optional", which is the default visibility state, no changes will be applied to let other plugins apply any changes they need.' => 'Եթե դաշտը դրված է որպես «ըստ ցանկության», որը տեսանելիության լռելյայն վիճակն է, ապա փոփոխություններ չեն կիրառվի, որպեսզի մյուս պլագինները կիրառեն իրենց անհրաժեշտ փոփոխությունները:','Hidden (remove field)' => 'Թաքնված (հեռացնել դաշտը)','Optional' => 'Ընտրովի','Required' => 'Պահանջվում է','Add shipping phone field to the checkout form.' => 'Ավելացրեք առաքման հեռախոսահամարի դաշտը վճարման ձևին:','Choose in which step to display the shipping phone field.' => 'Ընտրեք, թե որ քայլում կցուցադրվի առաքման հեռախոսի դաշտը:','Contact step' => 'Կոնտակտային քայլ','Billing phone' => 'Վճարային հեռախոս','Add billing phone field to the checkout form.' => 'Ավելացրեք վճարման հեռախոսահամարի դաշտը վճարման ձևին:','Choose in which step to display the billing phone field.' => 'Ընտրեք, թե որ քայլով կցուցադրվի վճարային հեռախոսի դաշտը:','Show country code beside the flag' => 'Ցույց տալ երկրի կոդը դրոշի կողքին','Show an example of a valid phone number inside phone fields' => 'Ցույց տվեք վավեր հեռախոսահամարի օրինակ հեռախոսի դաշտերում','Do not change placeholders' => 'Մի փոխեք տեղապահները','Show if not defined' => 'Ցույց տալ, եթե սահմանված չէ','Always show' => 'Միշտ ցույց տվեք','Order notes' => 'Պատվիրեք նշումներ','Define the visibility of the additional order notes field.' => 'Սահմանեք լրացուցիչ պատվերի նշումների դաշտի տեսանելիությունը:','Gift options' => 'Նվերների տարբերակներ','Allow customers to add a gift message and other gift related options to the order.' => 'Թույլ տվեք հաճախորդներին պատվերին ավելացնել նվեր հաղորդագրություն և նվերների հետ կապված այլ տարբերակներ:','Display the gift message as part of the order details table instead of a separate section' => 'Ցուցադրել նվեր հաղորդագրությունը որպես պատվերի մանրամասների աղյուսակի մաս՝ առանձին բաժնի փոխարեն','This option affects the order confirmation page (thank you page) and order details on account pages, emails and packing slips.' => 'Այս տարբերակը ազդում է պատվերի հաստատման էջի (շնորհակալություն էջ) և պատվերի մանրամասների վրա՝ հաշվի էջերում, էլ. նամակներում և փաթեթավորման կտրոններում:','Account matching' => 'Հաշվի համընկնում','Enable the account matching feature' => 'Միացնել հաշվի համապատասխանության գործառույթը','Associate the guest customer\'s orders with their existing account when an account already exists with the customer\'s contact details.' => 'Հյուր հաճախորդի պատվերները կապեք նրանց առկա հաշվի հետ, երբ հաշիվն արդեն գոյություն ունի հաճախորդի կոնտակտային տվյալների հետ:','Display message when an account exists with the email address provided' => 'Ցուցադրել հաղորդագրությունը, երբ գոյություն ունի հաշիվ՝ տրամադրված էլ.փոստի հասցեով','Replaces the account creation fields with a notification and option to log in. In some contexts, it might be recommended to leave this option disabled to protect the privacy of customers.' => 'Հաշվի ստեղծման դաշտերը փոխարինում է ծանուցումով և մուտք գործելու տարբերակով: Որոշ համատեքստերում խորհուրդ է տրվում անջատել այս տարբերակը՝ հաճախորդների գաղտնիությունը պաշտպանելու համար:','Dashboard' => 'Վահանակ','Integrations' => 'Ինտեգրումներ','License keys' => 'Լիցենզիայի բանալիներ','Visit our website for more information about our plugins and add-ons.' => 'Այցելեք մեր կայք մեր պլագինների և հավելումների մասին լրացուցիչ տեղեկությունների համար:','Order pay page' => 'Պատվիրել վճարման էջ','Order pay' => 'Պատվիրեք վճարում','Enable order pay page optimizations' => 'Միացնել պատվերի վճարման էջի օպտիմալացումը','Changes the layout of order pay page for existing orders pending payment from the customer.' => 'Փոխում է պատվերի վճարման էջի դասավորությունը առկա պատվերների համար, որոնք սպասվում են հաճախորդի կողմից վճարման:','Add widget areas to the order pay page' => 'Վիդջեթների տարածքներ ավելացրեք պատվերի վճարման էջում','These widget areas are used to add trust symbols and trust badges on the order pay page.' => 'Այս վիդջեթների տարածքներն օգտագործվում են պատվերի վճարման էջում վստահության նշաններ և վստահության նշաններ ավելացնելու համար:','Thank you page & order details layout' => 'Շնորհակալություն էջի և պատվերի մանրամասների դասավորությունը','Order details optimizations' => 'Պատվերի մանրամասների օպտիմալացում','Enable thank you page and order details optimizations' => 'Միացնել շնորհակալական էջը և պատվերի մանրամասների օպտիմալացումը','Changes the layout of order details on the thank you page and account pages.' => 'Փոխում է պատվերի մանրամասների դասավորությունը շնորհակալական էջում և հաշվի էջերում:','Enable order details customizations on email notifications' => 'Միացրեք պատվերի մանրամասների հարմարեցումները էլփոստի ծանուցումների վրա','Display new sections and change order of sections on email notifications. Styles of order details on email notifications remain unchanged.' => 'Ցուցադրել նոր բաժիններ և փոխել բաժինների հերթականությունը էլփոստի ծանուցումների վրա: Էլփոստի ծանուցումների պատվերի մանրամասների ոճերը մնում են անփոփոխ:','Thank you page' => 'Շնորհակալություն էջ','These options affect the thank you page, also known as order received or order confirmation pages.' => 'Այս ընտրանքները ազդում են շնորհակալության էջի վրա, որը նաև հայտնի է որպես պատվերի ստացված կամ պատվերի հաստատման էջեր:','Order details layout' => 'Պատվերի մանրամասների դասավորությունը','Display the order details with wide layout on the thank you page' => 'Ցուցադրեք պատվերի մանրամասները լայն դասավորությամբ շնորհակալական էջում','Add widget areas to the thank you page' => 'Շնորհակալության էջում ավելացրեք վիդջեթների տարածքներ','These widget areas are used to add trust symbols and trust badges on the thank you page.' => 'Այս վիդջեթների տարածքներն օգտագործվում են շնորհակալական էջում վստահության նշաններ և վստահության նշաններ ավելացնելու համար:','Order actions' => 'Պատվիրեք գործողություններ','Choose in which position to display the order actions.' => 'Ընտրեք, թե որ դիրքում կցուցադրվեն պատվերի գործողությունները:','Inside the order overview' => 'Պատվերի ակնարկի ներսում','After the order overview' => 'Պատվերի ակնարկից հետո','After order sections' => 'Պատվերից հետո բաժինները','Order status' => 'Պատվերի կարգավիճակը','Display the order status progress bar' => 'Ցուցադրել պատվերի կարգավիճակի առաջընթացի տողը','Choose in which position to display the section.' => 'Ընտրեք, թե որ դիրքում ցուցադրվի բաժինը:','After the order overview and payment instructions' => 'Պատվերի ակնարկից և վճարման հրահանգներից հետո','Before the order items section' => 'Նախքան պատվերի ապրանքների բաժինը','Inside the order items section' => 'Պատվերի կետերի բաժնում','After the order items section' => 'Պատվերի կետերի բաժնից հետո','On the sidebar' => 'Կողային գոտում','Order downloads' => 'Պատվիրեք ներբեռնումներ','Gift message' => 'Նվերի հաղորդագրություն','Tools' => 'Գործիքներ','Troubleshooting' => 'Անսարքությունների վերացում','Debug options' => 'Վրիպազերծման ընտրանքներ','Debug mode' => 'Վրիպազերծման ռեժիմ','Using debug mode affects the website performance. Only use this option while troubleshooting.' => 'Վրիպազերծման ռեժիմի օգտագործումը ազդում է կայքի աշխատանքի վրա: Օգտագործեք այս տարբերակը միայն անսարքությունների վերացման ժամանակ:','Load unminified assets' => 'Բեռնել չմինացված ակտիվները','Enhanced select fields' => 'Ընդլայնված ընտրված դաշտերը','Fix automatic zoom-in on form fields' => 'Ուղղել ձևի դաշտերի ավտոմատ խոշորացումը','Set <code>font-size</code> inside form fields to 16px' => '<code>font-size</code> ձևի դաշտերի ներսում սահմանեք 16px','Fluid Checkout' => 'Fluid Checkout','Settings' => 'Կարգավորումներ','Support' => 'Աջակցություն','<a target="_blank" href="%s">Upgrade to PRO</a> to unlock more options.' => '<a target="_blank" href="%s">Անցեք PRO-ի՝</a> ավելի շատ տարբերակներ բացելու համար:','(PRO)' => '(ՊՐՈ)','(experimental)' => '(փորձարարական)','Please verify your phone number.' => 'Խնդրում ենք հաստատել ձեր հեռախոսահամարը:','The Bluehost Plugin' => 'Bluehost Plugin','Custom fields' => 'Պատվերով դաշտեր','Enable custom shipping email field' => 'Միացնել հատուկ առաքման էլփոստի դաշտը','When enabled, the shipping email field from the Bluehost plugin will be added to the checkout form.' => 'Երբ միացված է, Bluehost հավելվածից առաքման էլփոստի դաշտը կավելացվի վճարման ձևին:','Captcha Pro by BestWebSoft' => 'Captcha Pro-ն BestWebSoft-ի կողմից','Captcha position' => 'Captcha դիրքը','Define the position to display the captcha section. Some positions might not work depending on the captcha type chosen.' => 'Սահմանեք captcha բաժինը ցուցադրելու դիրքը: Որոշ դիրքեր կարող են չաշխատել՝ կախված ընտրված captcha տեսակից:','Selecting a pickup point is required before proceeding.' => 'Շարունակելուց առաջ անհրաժեշտ է ընտրել հավաքման կետ:','Pickup point' => 'Վերցնելու կետ','Pickup point not selected yet.' => 'Վերցնելու կետը դեռ ընտրված չէ:','Pickup point:' => 'Վերցնելու կետ.','Mailchimp for WooCommerce' => 'Mailchimp WooCommerce-ի համար','Subscribe checkbox' => 'Բաժանորդագրվել վանդակը','Override the position for the subscribe checkbox on the checkout page and always display it on the contact step' => 'Չեղարկեք բաժանորդագրության վանդակի դիրքը վճարման էջում և միշտ ցուցադրեք այն կոնտակտային քայլում','Before Shipping Address' => 'Մինչև առաքումը Հասցե','(originally "%s")' => '(ի սկզբանե «%s»)','After Shipping Address' => 'Առաքումից հետո Հասցե','Selecting a collection point is required when shipping with FermoPoint.' => 'FermoPoint-ով առաքելիս անհրաժեշտ է հավաքման կետ ընտրել:','If checked informs typos in email to users. (This feature has been disabled because Fluid Checkout offers the feature. Changes to this option will not take effect)' => 'Նշված լինելու դեպքում օգտատերերին էլեկտրոնային փոստի տառասխալներ է հաղորդում: (Այս ֆունկցիան անջատված է, քանի որ Fluid Checkout-ն առաջարկում է այդ հնարավորությունը: Այս ընտրանքի փոփոխություններն ուժի մեջ չեն մտնի)','Enable Mail Check: (disabled feature)' => 'Միացնել փոստի ստուգումը. (անջատված գործառույթը)','Carrier:' => 'Փոխադրող:','Sendinblue - WooCommerce Email Marketing' => 'Sendinblue - WooCommerce էլփոստի շուկայավարում','Sign up checkbox position' => 'Գրանցվեք վանդակի դիրքը','Move the sign up checkbox to the contact step' => 'Տեղափոխեք գրանցման վանդակը կոնտակտային քայլ','When enabled, the checkbox will be moved to the contact step independently of the display location defined in the Sendinblue plugin settings.' => 'Երբ միացված է, վանդակը կտեղափոխվի կոնտակտային քայլ՝ անկախ Sendinblue հավելվածի կարգավորումներում սահմանված ցուցադրման վայրից:','Theme Betheme' => 'Թեմա Betheme','Checkout progress' => 'Ստուգման առաջընթաց','Output the checkout steps section from Betheme on the checkout, cart and order received pages.' => 'Արտադրեք վճարման քայլերի բաժինը Betheme-ից վճարման, զամբյուղի և պատվերի ստացված էջերում:','Theme Fennik' => 'Թեմա Ֆեննիկ','Breadcrumbs' => 'Հացի փշրանքներ','Output the breadcrumbs section from the Fennik theme when using Fluid Checkout header and footer.' => 'Fluid Checkout-ի վերնագիրն ու ստորագիրն օգտագործելիս դուրս բերեք հացի փշրանքների բաժինը Fennik թեմայից:','Theme Go' => 'Theme Go','My account layout' => 'Իմ հաշվի դասավորությունը','Enable wide layout on "My account" page.' => 'Միացնել լայն դասավորությունը «Իմ հաշիվը» էջում:','Theme Impreza' => 'Թեմա Impreza','Header' => 'Վերնագիր','Spacing for site header at the checkout page (in pixels)' => 'Կայքի վերնագրի տարածությունը վճարման էջում (պիքսելներով)','Only applicable when using the Impreza theme header at the checkout page.' => 'Կիրառելի է միայն վճարման էջում Impreza թեմայի վերնագիրն օգտագործելիս:','Theme Kapee' => 'Կապի թեմա','Output the checkout steps section from the Kapee theme on the checkout, cart and order received pages.' => 'Արտադրեք վճարման քայլերի բաժինը Kapee թեմայից դրամարկղի, զամբյուղի և պատվերի ստացված էջերում:','Theme Porto' => 'Թեմա Պորտո','Output the checkout steps section from the Porto theme on the checkout, cart and order received pages.' => 'Արտադրեք վճարման քայլերի բաժինը Porto թեմայից դրամարկղի, զամբյուղի և պատվերի ստացված էջերում:','Theme Pressmart' => 'Թեմա Pressmart','Output the checkout steps section from the Pressmart theme on the checkout, cart and order received pages.' => 'Դուրս բերեք վճարման քայլերի բաժինը Pressmart թեմայից դրամարկղի, զամբյուղի և պատվերի ստացված էջերում:','Theme The Gem' => 'Theme The Gem','Output the checkout steps section from The Gem theme when using Fluid Checkout header and footer.' => 'Fluid Checkout-ի վերնագիրն ու ստորագիրն օգտագործելիս դուրս բերեք վճարման քայլերի բաժինը The Gem թեմայից:','Theme Woodmart' => 'Թեմա Woodmart','Output the checkout steps section from the Woodmart theme when using Fluid Checkout header and footer.' => 'Արտադրեք վճարման քայլերի բաժինը Woodmart թեմայից, երբ օգտագործում եք Fluid Checkout վերնագիր և ստորագիր:','Checkout options' => 'Ստուգման ընտրանքներ','Disable the theme checkout options' => 'Անջատեք թեմայի վճարման ընտրանքները','The options display product image, quantity field, remove button and link to product page added by the theme are disabled by default.' => 'Արտադրանքի պատկերի ցուցադրման ընտրանքները, քանակի դաշտը, հեռացնել կոճակը և թեմայի կողմից ավելացված ապրանքի էջի հղումը լռելյայն անջատված են:','Theme Atomion' => 'Թեմա Atomion','Order progress' => 'Պատվերի առաջընթաց','Display order progress from the theme' => 'Ցուցադրել պատվերի առաջընթացը թեմայից','Display the form field labels visible on the page' => 'Ցուցադրել էջի վրա տեսանելի ձևի դաշտի պիտակները','It is recommended to keep this option enabled for a better user experience.' => 'Խորհուրդ է տրվում միացված պահել այս տարբերակը՝ օգտատերերի ավելի լավ փորձի համար:','Theme ZK Nito' => 'Թեմա ZK Nito','Add extra fields to the checkout form' => 'Հավելյալ դաշտեր ավելացրեք վճարման ձևին','Adds an extra shipping email and shipping phone field to the shipping address section.' => 'Առաքման հասցեի բաժնում ավելացնում է լրացուցիչ առաքման էլ.փոստ և առաքման հեռախոսահամար:','Go to the home page' => 'Գնացեք գլխավոր էջ','Skip to content' => 'Անցնել բովանդակությանը','Create an account' => 'Ստեղծեք հաշիվ','Log in to your account' => 'Մուտք գործեք ձեր հաշիվ','Already have an account?' => 'Արդեն ունե՞ք հաշիվ:','Logged in as %1$s. <a href="%2$s">Log out</a>' => 'Մուտք եք գործել որպես %1$s: <a href="%2$s">Դուրս գալ</a>','Your order has a total amount due of %s. No further payment is needed.' => 'Ձեր պատվերի ընդհանուր պարտքը կազմում է %s: Այլևս վճարման կարիք չկա:','Close and continue with checkout' => 'Փակեք և շարունակեք վճարումը','Continue' => 'Շարունակեք','Parcel terminal' => 'Ծանրոցների տերմինալ','<p>This widget has been replaced by Fluid Checkout. </p><p>When using Fluid Checkout, the checkout page needs to use the original WooCommerce shortcode <code>[woocommerce_checkout]</code> to work properly.</p><p>For more information, visit the Fluid Checkout documentation.</p>' => '<p>Այս վիջեթը փոխարինվել է Fluid Checkout-ով:</p><p> Fluid Checkout-ն օգտագործելիս վճարման էջը պետք է օգտագործի օրիգինալ WooCommerce կարճ կոդը <code>[woocommerce_checkout]</code> ՝ ճիշտ աշխատելու համար:</p><p> Լրացուցիչ տեղեկությունների համար այցելեք Fluid Checkout-ի փաստաթղթերը:</p>','Theme The7' => 'Թեմա The7','Additional header sections' => 'Վերնագրի լրացուցիչ բաժիններ','Output additional header sections if enabled in the theme settings.' => 'Արտադրեք վերնագրի լրացուցիչ բաժիններ, եթե միացված է թեմայի կարգավորումներում:','More information' => 'Լրացուցիչ տեղեկություններ','Pick a Locker' => 'Ընտրեք դարակ','Page template' => 'Էջի ձևանմուշ','Use `Order confirmation` page template for block-based themes' => 'Օգտագործեք «Պատվերի հաստատում» էջի ձևանմուշը բլոկային թեմաների համար','Only applies when using a block-based theme.' => 'Կիրառվում է միայն բլոկային թեմա օգտագործելիս։','WooCommerce Stripe Gateway' => 'WooCommerce Stripe Gateway','Payment form' => 'Վճարման ձև','Apply styles to the Stripe payment form fields' => 'Կիրառել ոճեր Stripe վճարման ձևի դաշտերում','When enabled, Fluid Checkout will apply styles optimized for compatibility with the plugin. You may want to disable this if you are using custom styles for the Stripe payment form fields.' => 'Միացված լինելու դեպքում, Fluid Checkout-ը կկիրառի պլագինի հետ համատեղելիության համար օպտիմիզացված ոճեր: Դուք կարող եք անջատել սա, եթե օգտագործում եք Stripe վճարման ձևի դաշտերի համար հատուկ ոճեր:','Theme Nyture' => 'Թեմատիկ Նյութուր','Output the checkout steps section from the Nyture theme when using Fluid Checkout.' => 'Fluid Checkout-ն օգտագործելիս արտածեք Nyture թեմայից վճարման քայլերի բաժինը։','Allows customers to make payments for orders that are either created manually by the store admin or not completed during checkout.' => 'Թույլ է տալիս հաճախորդներին կատարել վճարումներ այն պատվերների համար, որոնք կամ ձեռքով են ստեղծվել խանութի ադմինիստրատորի կողմից, կամ չեն ավարտվել վճարման ընթացքում։','The plugin WooCommerce Checkout Manager by Quadlayers is not compatible with Fluid Checkout' => 'Quadlayers-ի WooCommerce Checkout Manager հավելվածը համատեղելի չէ Fluid Checkout-ի հետ։','Company name field for billing address' => 'Ընկերության անվան դաշտ՝ հաշիվ-ապրանքագրի հասցեի համար','Change visibility for the company name field for the billing address section on the checkout form.' => 'Փոխեք ընկերության անվան դաշտի տեսանելիությունը վճարման ձևաթղթի վճարային հասցեի բաժնի համար։','Theme Bookshelf' => 'Թեմատիկ գրապահարան','Output the checkout steps section from the Bookshelf theme when using Fluid Checkout.' => 'Fluid Checkout-ն օգտագործելիս արտածեք Bookshelf թեմայից վճարման քայլերի բաժինը։','Account password' => 'Հաշվի գաղտնաբառ','An account will be created with the information provided at checkout when completing the order.' => 'Պատվերը կատարելիս կստեղծվի հաշիվ՝ պատվերի ձևակերպման ժամանակ տրամադրված տեղեկություններով։','Choose the style of the progress bar.' => 'Ընտրեք առաջընթացի գծի ոճը։','Bars' => 'Բարեր','Theme Ireca' => 'Թեմա՝ Իրեկա','WooCommerce page layout' => 'WooCommerce էջի դասավորություն','Force wide layout on WooCommerce pages' => 'WooCommerce էջերի վրա լայն դասավորություն պարտադրելը','This ensures the content section is not too narrow on WooCommerce pages including checkout, cart, order received, order pay and account pages.' => 'Սա ապահովում է, որ բովանդակության բաժինը չափազանց նեղ չլինի WooCommerce էջերում, ներառյալ վճարման, զամբյուղի, ստացված պատվերի, պատվերի վճարման և հաշվի էջերը։','WooCommerce Smart Coupons' => 'WooCommerce խելացի կտրոններ','Position on checkout page' => 'Դիրքը վճարման էջում','Choose where to display the available coupons section on the checkout page.' => 'Ընտրեք, թե որտեղ ցուցադրվի հասանելի կտրոնների բաժինը վճարման էջում։','Before the progress bar' => 'Առաջընթացի գոտուց առաջ','After the progress bar' => 'Առաջընթացի գոտուց հետո','Before coupon codes section' => 'Մինչև կտրոնի կոդերի բաժինը','Format phone numbers according to the rules for each country.' => 'Հեռախոսահամարները ձևաչափեք յուրաքանչյուր երկրի կանոններին համապատասխան։','Use precise phone number validation' => 'Օգտագործեք ճշգրիտ հեռախոսահամարի վավերացում','This is an experimental feature and may not work as expected in all setups. Use it with caution.' => 'Սա փորձարարական գործառույթ է և կարող է չաշխատել բոլոր կարգավորումներում սպասվածի պես։ Օգտագործեք այն զգուշությամբ։','Phone number validation types used when precise validation is enabled.' => 'Հեռախոսահամարի վավերացման տեսակները, որոնք օգտագործվում են ճշգրիտ վավերացման միացման դեպքում։','Mobile' => 'Բջջային','Fixed line' => 'Ֆիքսված գիծ','Toll free' => 'Անվճար զանգ','Or' => 'Կամ','Contact' => 'Կապ','Multi step' => 'Բազմաստիճան','2 columns' => '2 սյունակ','1 column' => '1 սյունակ','Before checkout steps' => 'Վճարումից առաջ քայլերը','When using the <em>"1 column"</em> checkout layout this option is always set to <em>"Before checkout steps"</em> and also applies to desktop view.' => '<em>«1 սյունակ»</em> վճարման դասավորությունն օգտագործելիս այս տարբերակը միշտ դրված է <em>«Վճարման քայլերից առաջ»</em> դիրքում և վերաբերում է նաև աշխատասեղանի տեսքին։','Position for the extra order summary section on mobile.' => 'Բջջային հեռախոսում պատվերի լրացուցիչ ամփոփման բաժնի դիրքը։','The option <em>"On the site header"</em> only applies when using the distraction-free header.' => '<em>«Կայքի վերնագրում»</em> տարբերակը գործում է միայն շեղող վերնագիրն օգտագործելիս։','On the site header (requires distraction-free header)' => 'Կայքի վերնագրի վրա (պահանջվում է շեղող գործոններից զերծ վերնագիր)','Initial state for the expansible order summary section on mobile.' => 'Բջջային հեռախոսում ընդարձակվող պատվերի ամփոփման բաժնի սկզբնական վիճակը։','We recommend setting it as <em>expanded</em> for the following countries due to regulatory requirements: <strong>Germany</strong>, <strong>Austria</strong>, <strong>Switzerland</strong>, <strong>Netherlands</strong>, <strong>Poland</strong>, <strong>Belgium</strong> and <strong>France</strong>.' => 'Կարգավորող պահանջների պատճառով խորհուրդ ենք տալիս այն սահմանել <em>ընդլայնված</em> հետևյալ երկրների համար՝ <strong>Գերմանիա</strong> , <strong>Ավստրիա</strong> , <strong>Շվեյցարիա</strong> , <strong>Նիդեռլանդներ</strong> , <strong>Լեհաստան</strong> , <strong>Բելգիա</strong> և <strong>Ֆրանսիա</strong> ։','Collapsed' => 'Ծալված է','Expanded' => 'Ընդլայնված','Do not show' => 'Չցուցադրել','yes' => 'այո','The shipping phone field may be forced as "required" if the billing address section is displayed after the shipping address section, and the billing phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'Առաքման հեռախոսահամարի դաշտը կարող է պարտադրված լինել որպես «պարտադիր», եթե հաշվի հասցեի բաժինը ցուցադրվում է առաքման հասցեի բաժնից հետո, և հաշվի հեռախոսահամարի դաշտը սահմանված է որպես «պարտադիր»։ Սա անհրաժեշտ է, որպեսզի առաքման հասցեն կարողանա պատճենվել հաշվի հասցեին, երբ այդ տարբերակը նշված է, հակառակ դեպքում հաճախորդը կարող է չկարողանալ լրացնել վճարման ձևը։','The billing phone field may be forced as "required" if the billing address section is displayed before the shipping address section, and the shipping phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'Հաշվարկային հեռախոսահամարի դաշտը կարող է պարտադրված լինել որպես «պարտադիր», եթե հաշվարկային հասցեի բաժինը ցուցադրվում է առաքման հասցեի բաժնից առաջ, և առաքման հեռախոսահամարի դաշտը սահմանված է որպես «պարտադիր»։ Սա անհրաժեշտ է, որպեսզի առաքման հասցեն կարողանա պատճենվել հաշվարկային հասցեին, երբ այդ տարբերակը նշված է, հակառակ դեպքում հաճախորդը կարող է չկարողանալ լրացնել վճարման ձևը։','Settings profiles' => 'Կարգավորումների պրոֆիլներ','Settings profile' => 'Կարգավորումների պրոֆիլ','You do not have permission to perform this action.' => 'Դուք այս գործողությունը կատարելու թույլտվություն չունեք։','You do not have permission to activate plugins.' => 'Դուք չունեք պլագիններ ակտիվացնելու թույլտվություն։','Missing plugin.' => 'Բացակայում է հավելվածը։','Plugin activated.' => 'Պլագինը ակտիվացված է։','The following changes will be applied:' => 'Կիրառվելու են հետևյալ փոփոխությունները.','Since Fluid Checkout 5.0, settings are saved differently. Legacy options are still stored in the database to allow downgrades to previous versions if needed.' => 'Fluid Checkout 5.0-ից սկսած, կարգավորումները պահվում են տարբեր կերպ: Հնացած տարբերակները դեռևս պահվում են տվյալների բազայում՝ անհրաժեշտության դեպքում նախորդ տարբերակներին անցնելու համար:','Your store has been running for about 2 weeks on the new settings so you could clean up legacy options stored in the database. Please note that after cleanup, if you need to downgrade to previous versions of the plugin it will use default values for all settings.' => 'Ձեր խանութը մոտ 2 շաբաթ է աշխատում է նոր կարգավորումներով, այնպես որ դուք կարող եք մաքրել տվյալների բազայում պահված հնացած տարբերակները: Խնդրում ենք նկատի ունենալ, որ մաքրումից հետո, եթե անհրաժեշտ լինի անցնել պլագինի նախորդ տարբերակներին, այն կօգտագործի բոլոր կարգավորումների համար լռելյայն արժեքները:','Fluid Checkout settings cleanup' => 'Fluid Checkout կարգավորումների մաքրում','Delete leftover options' => 'Ջնջել մնացորդային տարբերակները','Help us improve Fluid Checkout' => 'Օգնեք մեզ բարելավել Fluid Checkout-ը','Share anonymous site environment reports with Fluid Checkout to get faster support and help us improve compatibility and measure impact. No customer, user, or sensitive data are included. You can choose what is shared anytime from the Tools settings.' => 'Կիսվեք կայքի միջավայրի անանուն հաշվետվություններով Fluid Checkout-ի միջոցով՝ ավելի արագ աջակցություն ստանալու և մեզ օգնելու բարելավել համատեղելիությունը և չափել ազդեցությունը: Հաճախորդի, օգտատիրոջ կամ զգայուն տվյալներ չեն ներառվում: Դուք կարող եք ցանկացած պահի ընտրել, թե ինչ կիսվել «Գործիքներ» կարգավորումներից:','Enable site environment reports' => 'Միացնել կայքի միջավայրի հաշվետվությունները','Review settings' => 'Վերանայել կարգավորումները','This preview has expired. Reload the admin page to start a new preview.' => 'Այս նախադիտման ժամկետը լրացել է: Վերաբեռնեք ադմինիստրատորի էջը՝ նոր նախադիտում սկսելու համար:','Preview expired' => 'Նախադիտման ժամկետը լրացել է','Orders cannot be placed in the preview.' => 'Նախադիտման ժամանակ պատվերներ տեղադրել հնարավոր չէ։','Logging in is not available in the preview.' => 'Մուտք գործելը նախադիտման ռեժիմում հասանելի չէ։','Accounts cannot be created in the preview.' => 'Նախադիտման ժամանակ հաշիվներ չեն կարող ստեղծվել։','Requests to other sites are blocked in the preview.' => 'Նախադիտման ժամանակ այլ կայքերին ուղղված հարցումները արգելափակված են։','Processing…' => 'Մշակվում է…','Something went wrong. Please try again.' => 'Ինչ-որ բան սխալ է գնացել։ Խնդրում ենք կրկին փորձել։','Activate plugin' => 'Ակտիվացնել պլագինը','Fluid Checkout PRO - The complete checkout package' => 'Fluid Checkout PRO - Ամբողջական վճարման փաթեթ','All PRO features + all add-ons, one price. Design templates, optimized cart and order received pages, account matching, and much more.' => 'Բոլոր PRO հնարավորությունները + բոլոր հավելումները, մեկ գին: Դիզայնի ձևանմուշներ, օպտիմալացված զամբյուղի և պատվերի ստացման էջեր, հաշիվների համապատասխանեցում և շատ ավելին:','Optimized order pay page' => 'Օպտիմիզացված պատվերի վճարման էջ','Express checkout buttons from supported payment methods' => 'Արագ վճարման կոճակներ աջակցվող վճարման մեթոդներից','Delayed account creation' => 'Հաշվի ստեղծման ուշացում','Address autocomplete with Google Maps APIs' => 'Հասցեի ավտոմատ լրացում Google Maps API-ներով','Multiple saved addresses with the address book' => 'Բազմաթիվ պահպանված հասցեներ հասցեագրքով','EU-VAT assistant' => 'ԵՄ-ԱԱՀ օգնական','Hide this section' => 'Թաքցնել այս բաժինը','Learn more' => 'Իմանալ ավելին','Get early access' => 'Ստացեք վաղաժամ մուտք','Activate add-on' => 'Ակտիվացրեք հավելումը','Get more out of your checkout journey' => 'Ստացեք ավելին ձեր վճարման գործընթացից','Test API key' => 'API-ի փորձարկման բանալի','Guided setup' => 'Ուղղորդվող կարգավորում','Options' => 'Ընտրանքներ','Set up layout and design on the <a href="%s">checkout options</a>.' => 'Կարգավորեք դասավորությունը և դիզայնը <a href="%s">վճարման տարբերակներում</a> ։','Enable guest checkout and/or review <a href="%s">customer accounts settings</a>.' => 'Միացրեք հյուրի միջոցով վճարումը և/կամ վերանայեք <a href="%s">հաճախորդների հաշիվների կարգավորումները</a> ։','Enable optimized <a href="%1$s">cart</a>, <a href="%2$s">thank you</a> and <a href="%3$s">order pay</a> pages.' => 'Միացնել օպտիմալացված <a href="%1$s">զամբյուղի</a> , <a href="%2$s">շնորհակալության</a> և <a href="%3$s">պատվերի վճարման</a> էջերը։','Enable <a href="%s">address autocomplete</a> from Google Maps.' => 'Միացնել <a href="%s">հասցեի ավտոմատ լրացումը</a> Google Maps-ից։','Enable multiple saved addresses with <a href="%s">address book</a>.' => 'Միացնել բազմաթիվ պահպանված հասցեներ <a href="%s">հասցեագրքով</a> ։','Check if there are any <a href="%s">integration options</a> available for the theme or other plugins you have installed.' => 'Ստուգեք, թե արդյոք կան <a href="%s">ինտեգրման տարբերակներ</a> թեմայի կամ ձեր տեղադրած այլ պլագինների համար։','Get faster support and help us improve compatibility and measure impact. <a href="%s">Enable usage tracking</a> from the tools settings.' => 'Ստացեք ավելի արագ աջակցություն և օգնեք մեզ բարելավել համատեղելիությունը և չափել ազդեցությունը: <a href="%s">Միացրեք օգտագործման հետևումը</a> գործիքների կարգավորումներից:','Missing settings tab.' => 'Կարգավորումների ներդիրը բացակայում է։','Getting started' => 'Սկսնակների համար','<strong>Great! Your checkout page is now running on Fluid Checkout.</strong> Here are a few steps to get started:' => '<strong>Հիանալի է։ Ձեր վճարման էջը այժմ աշխատում է Fluid Checkout-ում։</strong> Ահա մի քանի քայլ՝ սկսելու համար։','Completed' => 'Ավարտված է','Preview report data' => 'Հաշվետվության տվյալների նախադիտում','Send now' => 'Ուղարկել հիմա','Auto-detect' => 'Ավտոմատ հայտնաբերում','Afrikaans' => 'Աֆրիկաանս','Albanian' => 'ալբանական','Amharic' => 'ամհարերեն','Arabic' => 'արաբերեն','Armenian' => 'հայ','Azerbaijani' => 'ադրբեջաներեն','Basque' => 'բասկերեն','Belarusian' => 'բելառուսական','Bengali' => 'բենգալերեն','Bosnian' => 'բոսնիերեն','Bulgarian' => 'բուլղարերեն','Burmese' => 'բիրմայերեն','Catalan' => 'կատալաներեն','Chinese' => 'չինական','Chinese (Simplified)' => 'Չինարեն (պարզեցված)','Chinese (Hong Kong)' => 'չինարեն (Հոնկոնգ)','Chinese (Traditional)' => 'Չինարեն (ավանդական)','Croatian' => 'խորվաթերեն','Czech' => 'չեխերեն','Danish' => 'դանիական','Dutch' => 'հոլանդերեն','English' => 'անգլերեն','English (Australian)' => 'Անգլերեն (ավստրալիական)','English (Great Britain)' => 'Անգլերեն (Մեծ Բրիտանիա)','Estonian' => 'էստոներեն','Farsi' => 'պարսկերեն','Finnish' => 'ֆիններեն','Filipino' => 'ֆիլիպիներեն','French' => 'ֆրանսերեն','French (Canadian)' => 'ֆրանսերեն (կանադական)','Galician' => 'գալիցիան','Georgian' => 'վրացական','German' => 'գերմաներեն','Greek' => 'հունարեն','Gujarati' => 'գուջարաթի','Hebrew' => 'եբրայերեն','Hindi' => 'հինդի','Hungarian' => 'հունգարերեն','Icelandic' => 'իսլանդերեն','Indonesian' => 'Ինդոնեզերեն','Italian' => 'իտալական','Japanese' => 'ճապոներեն','Kannada' => 'կաննադա','Kazakh' => 'ղազախերեն','Khmer' => 'քմերերեն','Korean' => 'կորեական','Kyrgyz' => 'ղրղզերեն','Lao' => 'Լաոս','Latvian' => 'լատվիական','Lithuanian' => 'լիտվերեն','Macedonian' => 'մակեդոներեն','Malay' => 'մալայերեն','Malayalam' => 'մալայալամ','Marathi' => 'մարաթհի','Mongolian' => 'մոնղոլական','Nepali' => 'նեպալերեն','Norwegian' => 'նորվեգական','Polish' => 'լեհերեն','Portuguese' => 'պորտուգալերեն','Portuguese (Brazil)' => 'Պորտուգալերեն (Բրազիլիա)','Portuguese (Portugal)' => 'Պորտուգալերեն (Պորտուգալիա)','Punjabi' => 'փենջաբերեն','Romanian' => 'ռումիներեն','Russian' => 'ռուսերեն','Serbian' => 'սերբերեն','Sinhalese' => 'սինհալերեն','Slovak' => 'սլովակերեն','Slovenian' => 'սլովեներեն','Spanish' => 'իսպաներեն','Spanish (Latin America)' => 'Իսպաներեն (Լատինական Ամերիկա)','Swahili' => 'սուահիլի','Swedish' => 'շվեդական','Tamil' => 'թամիլերեն','Telugu' => 'թելուգու','Thai' => 'թայերեն','Turkish' => 'թուրքերեն','Ukrainian' => 'ուկրաինական','Urdu' => 'ուրդու','Vietnamese' => 'վիետնամերեն','Zulu' => 'զուլու','Google address autocomplete' => 'Google հասցեի ավտոմատ լրացում','Google Places API version' => 'Google Places API-ի տարբերակը','Choose which version of the Google Places API to use. We recommend moving to the new Places API as soon as possible.' => 'Ընտրեք Google Places API-ի որ տարբերակն օգտագործել։ Խորհուրդ ենք տալիս հնարավորինս շուտ անցնել նոր Places API-ին։','We recommend using "Places API (New)" as effective March 1, 2025, Google will move the "Places API (Legacy)" version into Legacy status, meaning you will no longer be able to enable this service for new API keys and that that version of the API will eventually not be available anymore. Existing accounts already using the Legacy API may continue to work without disruptions.' => 'Խորհուրդ ենք տալիս օգտագործել «Places API (Նոր)»։ 2025 թվականի մարտի 1-ից սկսած՝ Google-ը «Places API (Legacy)» տարբերակը կտեղափոխի Legacy կարգավիճակի, ինչը նշանակում է, որ դուք այլևս չեք կարողանա միացնել այս ծառայությունը նոր API բանալիների համար, և API-ի այդ տարբերակը ի վերջո այլևս հասանելի չի լինի։ Legacy API-ն օգտագործող առկա հաշիվները կարող են շարունակել աշխատել առանց խափանումների։','(Recommended)' => '(Խորհուրդ է տրվում)','Google API key' => 'Google API բանալի','Paste your Google API key and use the test button to confirm it works for this website. Make sure the key is valid and allowed for your domain, otherwise the address field might get blocked preventing customers from completing their orders.' => 'Տեղադրեք ձեր Google API բանալին և օգտագործեք փորձարկման կոճակը՝ հաստատելու համար, որ այն աշխատում է այս կայքի համար: Համոզվեք, որ բանալին վավեր է և թույլատրված է ձեր տիրույթի համար, հակառակ դեպքում հասցեի դաշտը կարող է արգելափակվել՝ խանգարելով հաճախորդներին կատարել իրենց պատվերները:','Enable Google address autocomplete' => 'Միացնել Google հասցեի ավտոմատ լրացումը','Enable address autocompletion using the Google Maps APIs.' => 'Միացնել հասցեների ավտոմատ լրացումը՝ օգտագործելով Google Maps API-ները:','Google API language' => 'Google API լեզու','This language will be used to display the Google Places API address suggestions and addresses will also be autocompleted in this language.' => 'Այս լեզուն կօգտագործվի Google Places API հասցեների առաջարկները ցուցադրելու համար, և հասցեները նույնպես ավտոմատ կերպով կլրացվեն այս լեզվով։','Result types' => 'Արդյունքների տեսակները','Leave empty to accept any type of results, which usually yields better matching results. <a href="%s" target="_blank">See documentation for more details</a>. <br>Select up to 5 types of address search results to return on address autocomplete fields. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'Թողեք դատարկ՝ ցանկացած տեսակի արդյունք ընդունելու համար, որը սովորաբար ավելի լավ համընկնող արդյունքներ է տալիս: <a href="%s" target="_blank">Ավելի մանրամասն տեղեկությունների համար տե՛ս փաստաթղթերը</a> :<br> Ընտրեք մինչև 5 տեսակի հասցեների որոնման արդյունքներ՝ հասցեների ավտոմատ լրացման դաշտերում ցուցադրելու համար։<br> <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">Աջակցվող տեսակների</a> մասին ավելին իմանալու համար այցելեք Google Maps-ի փաստաթղթերը։','Result types (Legacy API)' => 'Արդյունքների տեսակներ (Legacy API)','Which type of address search results to return when using Places API (Legacy). <br>Visit the documentation of the Legacy Google Places API to learn more about the <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">supported types</a>.' => 'Ինչ տեսակի հասցեի որոնման արդյունքներ վերադարձնել Places API-ի (Legacy) օգտագործման ժամանակ։<br> <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">Աջակցվող տեսակների</a> մասին ավելին իմանալու համար այցելեք Legacy Google Places API-ի փաստաթղթերը։','Company fields' => 'Ընկերության դաշտեր','Enable autocomplete for the company name if available' => 'Միացրեք ընկերության անվան ավտոմատ լրացումը, եթե հնարավոր է','Enable autocompletion of the company field with the company name information when returned from the Google Maps APIs.' => 'Միացնել ընկերության դաշտի ավտոմատ լրացումը ընկերության անվանման տեղեկատվությամբ, երբ այն վերադարձվում է Google Maps API-ներից:','Business search' => 'Գործարար որոնում','Enable search for businesses in the company field' => 'Միացնել ընկերության ոլորտում բիզնեսների որոնումը','Enable suggestion of addresses associated with a business when typing in the company field, then autocomplete all addresses fields when a business is selected from the suggestions.' => 'Ընկերության դաշտում մուտքագրելիս միացրեք բիզնեսի հետ կապված հասցեների առաջարկը, այնուհետև ավտոմատ կերպով լրացրեք բոլոր հասցեների դաշտերը, երբ բիզնեսը ընտրվում է առաջարկներից:','Company result types' => 'Ընկերության արդյունքների տեսակները','Select up to 5 types of address search results to return on autocomplete company fields. <br>Recommended value is <code>establishment</code>, which includes most types of businesses. <br>Leave empty to accept any type of results, including results that are not related to businesses. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'Ընտրեք մինչև 5 տեսակի հասցեների որոնման արդյունքներ՝ ավտոմատ լրացվող ընկերության դաշտերում ցուցադրելու համար։<br> Առաջարկվող արժեքը <code>establishment</code> է, որը ներառում է բիզնեսների մեծ մասը։<br> Թողեք դատարկ՝ ցանկացած տեսակի արդյունք ընդունելու համար, ներառյալ այն արդյունքները, որոնք կապված չեն բիզնեսների հետ։<br> <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">Աջակցվող տեսակների</a> մասին ավելին իմանալու համար այցելեք Google Maps-ի փաստաթղթերը։','Google logo' => 'Google-ի լոգո','Show text and logo "Powered by Google"' => 'Ցուցադրել տեքստը և լոգոն՝ «Google-ի կողմից մշակված»','When checked, the text and logo "Powered by Google" will be displayed at the bottom of the address autocomplete suggestions box.' => 'Նշելու դեպքում, «Powered by Google» տեքստը և լոգոն կցուցադրվեն հասցեի ավտոմատ լրացման առաջարկների պատուհանի ներքևի մասում։','Brasil API address autocomplete' => 'Brasil API հասցեի ավտոմատ լրացում','Brasil API' => 'Բրազիլիայի API','Enable Brasil API address autocomplete for CEP fields' => 'Միացնել Brasil API հասցեի ավտոմատ լրացումը CEP դաշտերի համար','Use Brasil API to retrieve and autofill addresses using the CEP/Postcode field. Only relevant for Brazilian addresses.' => 'Օգտագործեք Brasil API-ը՝ հասցեները CEP/Փոստային ինդեքս դաշտի միջոցով ստանալու և ավտոմատ լրացնելու համար: Համապատասխանում է միայն բրազիլական հասցեներին:','API version' => 'API-ի տարբերակ','Choose which version of the Brasil API CEP method to use.' => 'Ընտրեք Brasil API CEP մեթոդի որ տարբերակն օգտագործել։','Address book migration' => 'Հասցեների գրքի տեղափոխում','WooCommerce addresses' => 'WooCommerce հասցեներ','Copy existing shipping and billing addresses from WooCommerce into the customers\' address book.' => 'Պատճենեք WooCommerce-ի առկա առաքման և հաշվառման հասցեները հաճախորդների հասցեների գրքում։','Enable the address book feature' => 'Միացնել հասցեագրքի գործառույթը','Allow customers to save multiple addresses and define the default address to be used for shipping and billing.' => 'Թույլ տվեք հաճախորդներին պահպանել բազմաթիվ հասցեներ և սահմանել առաքման և հաշվառման համար օգտագործվող լռելյայն հասցեն։','Address labels' => 'Հասցեի պիտակներ','Allow customers to add a custom label for each address' => 'Թույլատրեք հաճախորդներին ավելացնել անհատական պիտակ յուրաքանչյուր հասցեի համար','Address labels make it easier to for customers to distinguish between their saved addresses (ie.: "Mom\'s House"). The address labels are private to the customers, and will not be displayed or printed on the order details page or invoices.' => 'Հասցեի պիտակները հեշտացնում են հաճախորդների համար իրենց պահպանված հասցեների տարբերակումը (օրինակ՝ «Մայրիկի տուն»): Հասցեի պիտակները հասանելի են միայն հաճախորդներին և չեն ցուցադրվի կամ տպագրվի պատվերի մանրամասների էջում կամ հաշիվ-ապրանքագրերում:','Display layout' => 'Էկրանի դասավորությունը','Choose how saved addresses are displayed at checkout and on the cart.' => 'Ընտրեք, թե ինչպես են պահպանված հասցեները ցուցադրվելու վճարման ժամանակ և զամբյուղում։','Applies at checkout and on the cart. Saved addresses on the account page always use the cards layout.' => 'Գործում է վճարման ժամանակ և զամբյուղում։ Հաշվի էջում պահպանված հասցեները միշտ օգտագործում են քարտերի դասավորությունը։','Address cards' => 'Հասցեի քարտեր','Address list' => 'Հասցեների ցանկ','Dropdown field' => 'Իջնող ցանկի դաշտ','Address search' => 'Հասցեի որոնում','Show address search filter on frontend when customer has at least this number of saved addresses available.' => 'Ցուցադրել հասցեների որոնման ֆիլտրը ինտերֆեյսում, երբ հաճախորդն ունի առնվազն այս քանակությամբ պահպանված հասցեներ։','Not used when display layout is set to dropdown field.' => 'Չի օգտագործվում, երբ ցուցադրման դասավորությունը սահմանված է որպես իջնող ցանկի դաշտ։','Addresses' => 'Հասցեներ','Enable cart page optimizations to see more options' => 'Միացրեք զամբյուղի էջի օպտիմալացումները՝ ավելի շատ տարբերակներ տեսնելու համար','Sticky order summary' => 'Կպչուն պատվերի ամփոփում','Select position where to display the coupon codes section on the cart page. Only applicable when AJAX cart is enabled, and if use of coupon codes are enabled in the WooCommerce settings.' => 'Ընտրեք զամբյուղի էջում կտրոնների կոդերի բաժնի ցուցադրման դիրքը: Կիրառելի է միայն այն դեպքում, երբ AJAX զամբյուղը միացված է, և եթե կտրոնների կոդերի օգտագործումը միացված է WooCommerce կարգավորումներում:','Layout of cross-sell' => 'Խաչաձև վաճառքի դասավորություն','Cross-sells displayed' => 'Խաչաձև վաճառքների ցուցադրում','Items' => 'Ապրանքներ','Cart page optimization' => 'Զամբյուղի էջի օպտիմալացում','Give your cart the same clear, conversion-focused layout as your checkout.' => 'Ձեր զամբյուղին տվեք նույն պարզ, փոխակերպման վրա կենտրոնացած դասավորությունը, ինչ ձեր վճարման ձևը։','Match the cart layout to the checkout page for a consistent purchase journey.' => 'Համապատասխանեցրեք զամբյուղի դասավորությունը վճարման էջին՝ գնման հետևողական ընթացքի համար։','Keep the cart always updated in the background, no full page reloads when quantities change.' => 'Զամբյուղը միշտ թարմացված պահեք ֆոնային ռեժիմում, քանակի փոփոխության դեպքում էջը ամբողջությամբ չի բեռնվում։','Place coupon codes, shipping, and cross-sells exactly where they convert best.' => 'Տեղադրեք կտրոնի կոդերը, առաքման կոդերը և խաչաձև վաճառքները հենց այնտեղ, որտեղ դրանք ամենաշատն են փոխարկվում։','Keep the order summary visible while scrolling, and add trust symbols where shoppers need reassurance.' => 'Պատվերի ամփոփումը տեսանելի պահեք սահեցնելիս և ավելացրեք վստահության խորհրդանիշներ այնտեղ, որտեղ գնորդները վստահության կարիք ունեն։','Columns' => 'Սյունակներ','General styles for the checkout steps, order summary and other sections. Applies to other checkout, cart, thank you (order received), and view order pages.' => 'Վճարման քայլերի, պատվերի ամփոփման և այլ բաժինների ընդհանուր ոճերը: Կիրառվում է վճարման, զամբյուղի, շնորհակալություն հայտնելու (պատվերը ստացվել է) և պատվերի դիտման այլ էջերի համար:','When using the <em>"1 column"</em> layout with the <em>"Split"</em> design template, a right column is shown only if the page sidebar widget area is active (Checkout Sidebar, Cart Sidebar, or Order Received Sidebar). Otherwise the page stays as a single column with Split styles.' => 'Երբ <em>«1 սյունակ»</em> դասավորությունն օգտագործվում է <em>«Բաժանել»</em> դիզայնի ձևանմուշի հետ, աջ սյունը ցուցադրվում է միայն այն դեպքում, եթե էջի կողային վահանակի վիջեթի տարածքը ակտիվ է (Վճարման կողային վահանակ, Զամբյուղի կողային վահանակ կամ Պատվերի ստացման կողային վահանակ): Հակառակ դեպքում էջը մնում է որպես մեկ սյունակ՝ «Բաժանել» ոճերով:','Split column background' => 'Սյունակի բաժանման ֆոն','Choose a background color for the Split design secondary column. Leave empty to use the order summary background color.' => 'Ընտրեք ֆոնի գույն «Բաժանել դիզայնը» երկրորդական սյան համար: Թողեք դատարկ՝ կարգի ամփոփման ֆոնի գույնն օգտագործելու համար:','Page templates' => 'Էջի ձևանմուշներ','Checkout template' => 'Վճարման ձևանմուշ','Recommended for fewer distractions at checkout. <a href="https://baymard.com/blog/cart-abandonment" target="_blank">Read the research about cart abandonment</a>.' => 'Խորհուրդ է տրվում վճարման ժամանակ շեղող գործոնները նվազեցնելու համար։ <a href="https://baymard.com/blog/cart-abandonment" target="_blank">Կարդացեք զամբյուղը լքելու վերաբերյալ հետազոտությունը</a> ։','Sticky progress bar' => 'Կպչուն առաջընթացի գոտի','Progress bar style' => 'Ընթացքի գոտու ոճը','Order totals' => 'Պատվերի ընդհանուր գումարը','Background color' => 'Ֆոնի գույնը','Action link' => 'Գործողության հղում','Mobile order summary' => 'Բջջային հեռախոսով պատվերի ամփոփում','Mobile initial state' => 'Բջջային հեռախոսի սկզբնական վիճակը','Enable editing cart items at checkout' => 'Միացնել զամբյուղի ապրանքների խմբագրումը վճարման ժամանակ','Allow customers to change product quantities or remove items directly at the checkout page.' => 'Թույլ տվեք հաճախորդներին փոխել ապրանքի քանակը կամ հեռացնել ապրանքները անմիջապես վճարման էջում։','Cart item errors' => 'Զամբյուղի ապրանքների սխալներ','Only applicable when coupon code is displayed as a separate section on the checkout or cart pages, and if use of coupon codes are enabled in the WooCommerce settings.' => 'Կիրառելի է միայն այն դեպքում, երբ կտրոնի կոդը ցուցադրվում է որպես առանձին բաժին վճարման կամ զամբյուղի էջերում, և եթե կտրոնի կոդերի օգտագործումը միացված է WooCommerce-ի կարգավորումներում։','Coupon codes position' => 'Կտրոնի կոդերի դիրքը','Apply coupon button' => 'Կտրոնի կիրառման կոճակ','Select style of the "apply coupon" button.' => 'Ընտրեք «կիրառել կտրոնը» կոճակի ոճը։','Address line 2' => 'Հասցեի 2-րդ տող','This setting is shared between the Checkout and Local pickup sections. On the Local pickup section, it also decides whether the Ship/Pickup selector shows inside the shipping method section (before the address) or as a separate section (after).' => 'Այս կարգավորումը համատեղ օգտագործվում է «Վճարման ձև» և «Տեղական վերցման» բաժինների միջև: «Տեղական վերցման» բաժնում այն նաև որոշում է, թե արդյոք «Առաքում/Վերցման» ընտրիչը կցուցադրվի առաքման մեթոդի բաժնում (հասցեից առաջ), թե՞ որպես առանձին բաժին (հետո):','Customer accounts' => 'Հաճախորդների հաշիվներ','Guest checkout' => 'Հյուրի վճարում','Guest checkout, login, and account creation options from the WooCommerce Accounts settings page. They are managed here for your convenience, and so you can use different values per settings profile.' => 'Հյուրի կողմից վճարման, մուտք գործելու և հաշվի ստեղծման տարբերակները WooCommerce հաշիվների կարգավորումների էջից են: Դրանք կառավարվում են այստեղ՝ ձեր հարմարության համար, ուստի կարող եք օգտագործել տարբեր արժեքներ յուրաքանչյուր կարգավորումների պրոֆիլի համար:','Allow customers to checkout without an account' => 'Թույլատրել հաճախորդներին վճարում կատարել առանց հաշվի','<strong>Recommended</strong> so customers are not asked to create an account or log in during checkout, which can lower conversion rates.' => '<strong>Խորհուրդ է տրվում</strong> , որպեսզի հաճախորդներից չպահանջվի հաշիվ ստեղծել կամ մուտք գործել վճարման ընթացքում, ինչը կարող է իջեցնել փոխակերպման մակարդակը։','When disabled, customers must log in or create an account to complete the purchase.' => 'Երբ անջատված է, հաճախորդները պետք է մուտք գործեն կամ ստեղծեն հաշիվ՝ գնումն ավարտելու համար։','Login at checkout' => 'Մուտք գործեք վճարման ժամանակ','Enable log-in during checkout' => 'Միացնել մուտքը վճարման ընթացքում','Show a link for returning customers to log in from the checkout page.' => 'Ցուցադրել հղում վերադարձող հաճախորդների համար՝ վճարման էջից մուտք գործելու համար։','Account creation' => 'Հաշվի ստեղծում','Allow customers to create an account during checkout' => 'Թույլատրել հաճախորդներին ստեղծել հաշիվ վճարման ընթացքում','Customers can create an account before placing their order.' => 'Հաճախորդները կարող են հաշիվ ստեղծել պատվերը տեղադրելուց առաջ։','Allow customers to create an account from the My account page' => 'Թույլատրել հաճախորդներին ստեղծել հաշիվ «Իմ հաշիվը» էջից','Customers can register a new account from the My account page.' => 'Հաճախորդները կարող են գրանցել նոր հաշիվ «Իմ հաշիվը» էջից։','Username' => 'Օգտատիրոջ անուն','Generate from customer\'s name' => 'Ստեղծել հաճախորդի անունից','<strong>Recommended</strong> so customers are not asked to choose a username during checkout, which can lower conversion rates.' => '<strong>Խորհուրդ է տրվում</strong> , որպեսզի հաճախորդներից չխնդրվի ընտրել օգտանուն վճարման ժամանակ, ինչը կարող է իջեցնել փոխակերպման մակարդակները։','A username is generated from the customer name, or from the email address when a name cannot be used.' => 'Օգտատիրոջ անունը ստեղծվում է հաճախորդի անունից կամ էլեկտրոնային փոստի հասցեից, երբ անունը չի կարող օգտագործվել։','Password' => 'Գաղտնաբառ','Send password setup link' => 'Ուղարկել գաղտնաբառի կարգավորման հղումը','<strong>Recommended</strong> so customers are not asked to set a password during checkout, which can lower conversion rates.' => '<strong>Խորհուրդ է տրվում</strong> , որպեսզի հաճախորդներից չպահանջվի գաղտնաբառ սահմանել վճարման ժամանակ, ինչը կարող է նվազեցնել փոխակերպման մակարդակը։','Customers receive an email to create their password securely.' => 'Հաճախորդները ստանում են էլեկտրոնային նամակ՝ իրենց գաղտնաբառն անվտանգ կերպով ստեղծելու համար։','Let registered customers complete checkout without logging in and associate the order with their existing account when contact details match.' => 'Թույլ տվեք գրանցված հաճախորդներին ավարտել վճարումը առանց մուտք գործելու և կապել պատվերը իրենց առկա հաշվի հետ, երբ կոնտակտային տվյալները համընկնում են։','Existing account message' => 'Գոյություն ունեցող հաշվի հաղորդագրություն','Let customers create an account after placing their order, from the thank you page.' => 'Թույլ տվեք հաճախորդներին ստեղծել հաշիվ պատվերը տեղադրելուց հետո՝ շնորհակալության էջից։','Options in this section are available when guest checkout and account matching are enabled. Enable both features above to configure delayed account creation.' => 'Այս բաժնի ընտրանքները հասանելի են, երբ հյուրի վճարումը և հաշվի համապատասխանեցումը միացված են: Միացրեք վերը նշված երկու գործառույթները՝ հաշվի ստեղծման հետաձգումը կարգավորելու համար:','Enable delayed account creation' => 'Միացնել հաշվի ստեղծման հետաձգումը','Enable delayed account creation when both guest checkout and account matching are enabled.' => 'Միացրեք հաշվի ստեղծման հետաձգումը, երբ միացված են և՛ հյուրի վճարումը, և՛ հաշվի համընկնում:','Section position' => 'Բաժնի դիրքը','Before customer details section' => 'Հաճախորդի տվյալների բաժնից առաջ','After customer details section' => 'Հաճախորդի տվյալների բաժնից հետո','Account creation benefits' => 'Հաշվի ստեղծման առավելությունները','Leaving the field empty will display the default text.' => 'Դաշտը դատարկ թողնելը կցուցադրի լռելյայն տեքստը։','Inline buttons' => 'Ներտող կոճակներ','Required fields' => 'Պարտադիր դաշտեր','Enable gift message fields at checkout' => 'Միացրեք նվերի հաղորդագրության դաշտերը վճարման ժամանակ','Expanded gift message' => 'Ընդլայնված նվերի հաղորդագրություն','Display gift message field always expanded' => '«Ցուցադրել նվերի հաղորդագրության դաշտը միշտ ընդարձակված»','Gift message in order details' => 'Նվերի հաղորդագրություն պատվերի մանրամասներում','No integrations available at the moment on this section. The options related to each plugin and theme will only appear here when that plugin or theme is activated.' => 'Այս բաժնում այս պահին ինտեգրացիաներ հասանելի չեն: Յուրաքանչյուր պլագինի և թեմայի հետ կապված տարբերակները կհայտնվեն այստեղ միայն այն ժամանակ, երբ այդ պլագինը կամ թեման ակտիվացված է:','Phone fields' => 'Հեռախոսային դաշտեր','Field visibility' => 'Դաշտի տեսանելիություն','Field position' => 'Դաշտային դիրք','Phone country code & validation' => 'Հեռախոսահամարի երկրի կոդ և վավերացում','Country' => 'Երկիր','Enable country on phone fields' => 'Միացնել երկիրը հեռախոսի դաշտերում','Filter countries for shipping or billing' => 'Զտեք երկրները առաքման կամ հաշվառման համար','Limit the country selector on each phone field to the countries allowed for shipping or billing on your store.' => 'Սահմանափակեք յուրաքանչյուր հեռախոսահամարի դաշտում երկրի ընտրիչը ձեր խանութում առաքման կամ հաշվառման համար թույլատրված երկրների համար։','Validation' => 'Հաստատում','Enable simple validation based on country rules' => 'Միացնել երկրի կանոնների հիման վրա պարզ վավերացումը','Checks that the phone number is valid for the selected country, including country code and length.' => 'Ստուգում է, որ հեռախոսահամարը վավեր է ընտրված երկրի համար, ներառյալ երկրի կոդը և երկարությունը։','Stricter check that the number is a valid mobile, fixed line, or other accepted type for the selected country. May reject some valid numbers.' => 'Ավելի խիստ ստուգեք, որ համարը վավեր բջջային, ստացիոնար կամ ընտրված երկրի համար ընդունված այլ տեսակի է։ Որոշ վավեր համարներ կարող են մերժվել։','Validation types' => 'Հաստատման տեսակները','Placeholders' => 'Տեղապահներ','No license keys to manage at the moment. License keys will appear here when a licensed Fluid Checkout plugin or add-on is active.' => 'Այս պահին լիցենզիայի բանալիներ չկան կառավարելու համար: Լիցենզիայի բանալիները կհայտնվեն այստեղ, երբ ակտիվ լինի Fluid Checkout-ի լիցենզավորված պլագինը կամ հավելումը:','Default delivery type' => 'Լռելյայն առաքման տեսակ','Choose which delivery type will be selected by default.' => 'Ընտրեք, թե որ առաքման տեսակն է ընտրվելու լռելյայն։','Shipping zone fields' => 'Առաքման գոտու դաշտեր','Choose which fields will be displayed for the local pickup shipping zone filter fields. Leave empty to show all available options.' => 'Ընտրեք, թե որ դաշտերը կցուցադրվեն տեղական վերցման առաքման գոտու ֆիլտրի դաշտերի համար: Թողեք դատարկ՝ բոլոր հասանելի տարբերակները ցուցադրելու համար:','These fields will be displayed as a filter for the local pickup shipping methods. Some fields might still appear at checkout when not selected here, if compatible plugins require them to work properly.' => 'Այս դաշտերը կցուցադրվեն որպես տեղական վերցման առաքման մեթոդների ֆիլտր: Որոշ դաշտեր կարող են դեռևս հայտնվել վճարման ժամանակ, եթե այստեղ չընտրվեն, եթե համատեղելի պլագինները պահանջում են, որ դրանք ճիշտ աշխատեն:','Order shipping address' => 'Պատվերի առաքման հասցե','Order pay page optimization' => 'Պատվերի վճարման էջի օպտիմալացում','Give unpaid orders the same clear, conversion-focused layout as checkout.' => 'Չվճարված պատվերներին տվեք նույն պարզ, փոխակերպման վրա կենտրոնացած դասավորությունը, ինչ վճարման ավարտին։','Optimize the layout of the order pay page for orders pending payment.' => 'Օպտիմալացրեք պատվերի վճարման էջի դասավորությունը վճարման սպասող պատվերների համար։','Match the order pay experience to your checkout for a consistent purchase journey.' => 'Համապատասխանեցրեք պատվերի վճարման փորձը ձեր վճարման գործընթացին՝ հետևողական գնման գործընթաց ապահովելու համար։','Add trust symbols and badges where shoppers need reassurance before paying.' => 'Ավելացրեք վստահության խորհրդանիշներ և կրծքանշաններ այն վայրերում, որտեղ գնորդները վճարումից առաջ վստահության կարիք ունեն։','Thank you page optimization' => 'Շնորհակալություն էջի օպտիմալացում','Make the thank you page and order details clearer for customers after they buy.' => 'Գնումից հետո հաճախորդների համար ավելի հստակ դարձրեք շնորհակալության էջը և պատվերի մանրամասները։','Optimize the thank you page and account order details with a clearer layout.' => 'Օպտիմալացրեք շնորհակալության էջը և հաշվի պատվերի մանրամասները՝ ավելի հստակ դասավորությամբ։','Show order status progress, actions, downloads, and notes where they make sense.' => 'Ցուցադրել պատվերի կարգավիճակի առաջընթացը, գործողությունները, ներբեռնումները և նշումները, որտեղ դրանք իմաստ ունեն։','Customize order details sections on email notifications.' => 'Անհատականացրեք պատվերի մանրամասների բաժինները էլփոստային ծանուցումների մեջ։','Add trust symbols and badges where shoppers need reassurance after purchase.' => 'Ավելացրեք վստահության խորհրդանիշներ և կրծքանշաններ այն վայրերում, որտեղ գնորդները գնումից հետո վստահության կարիք ունեն։','Email notifications' => 'Էլ․փոստի ծանուցումներ','Enable thank you page and order details optimizations to see more options' => 'Միացրեք շնորհակալության էջը և պատվերի մանրամասների օպտիմալացումը՝ ավելի շատ տարբերակներ տեսնելու համար','Use wide layout on thank you page' => 'Օգտագործեք լայն դասավորություն շնորհակալության էջում','These options affect the thank you page, view order details on account pages and on email notifications.' => 'Այս տարբերակները ազդում են շնորհակալության էջի, հաշվի էջերում պատվերի մանրամասների դիտման և էլփոստային ծանուցումների վրա։','Save settings' => 'Պահպանել կարգավորումները','Docs' => 'Փաստաթղթեր','Cart' => 'Զամբյուղ','Thank you' => 'Շնորհակալություն','Address autocomplete' => 'Հասցեի ավտոմատ լրացում','Trust badges' => 'Վստահության նշաններ','You do not have permission to save these settings.' => 'Դուք չունեք այս կարգավորումները պահպանելու թույլտվություն։','Invalid save request.' => 'Պահպանման հարցումը անվավեր է։','Your settings have been saved.' => 'Ձեր կարգավորումները պահպանվել են։','Saving...' => 'Պահպանվում է...','Settings could not be saved. Please try again.' => 'Կարգավորումները չհաջողվեց պահպանել։ Խնդրում ենք կրկին փորձել։','Dismiss notice' => 'Մերժել ծանուցումը','Open settings menu' => 'Բացել կարգավորումների ցանկը','Close settings menu' => 'Փակել կարգավորումների ցանկը','Preview' => 'Նախադիտում','Expand preview' => 'Բացել նախադիտումը','Collapse preview' => 'Ծալել նախադիտումը','Show header and footer' => 'Ցուցադրել վերնագիրը և ստորին մասը','Hide header and footer' => 'Թաքցնել վերնագիրը և ստորոտը','Page preview' => 'Էջի նախադիտում','Preview viewport' => 'Նախադիտման պատուհան','Tablet' => 'Պլանշետ','Desktop' => 'Համակարգիչ','Preview width' => 'Նախադիտման լայնությունը','Decrease width' => 'Նվազեցնել լայնությունը','Preview width in pixels' => 'Նախադիտման լայնությունը պիքսելներով','Increase width' => 'Մեծացնել լայնությունը','Preview as' => 'Նախադիտել որպես','Guest' => 'Հյուր','Logged in' => 'Մուտք գործեցիք','Preview page' => 'Նախադիտման էջ','Expand preview for a closer look' => 'Ընդարձակել նախադիտումը՝ ավելի մանրամասն դիտելու համար','Available with %s.' => 'Հասանելի է %s-ով։','Turn them on' => 'Միացրեք դրանք','Optimizations for this page are turned off. %s to preview the page.' => 'Այս էջի օպտիմալացումները անջատված են։ %s՝ էջը նախադիտելու համար։','%s preview' => '%s նախադիտում','Isolated session · nothing is saved' => 'Մեկուսացված նիստ · ոչինչ չի պահպանվել','Usage tracking' => 'Օգտագործման հետևում','Send non-sensitive site environment reports to help Fluid Checkout improve compatibility. Reports are not sent until enabled in the options below.' => 'Ուղարկեք ոչ զգայուն կայքի միջավայրի մասին հաշվետվություններ՝ Fluid Checkout-ին համատեղելիությունը բարելավելու համար: Հաշվետվությունները չեն ուղարկվում, մինչև դրանք չմիացվեն ստորև նշված տարբերակներում:','Send usage tracking reports to Fluid Checkout' => 'Ուղարկել օգտագործման հետևման հաշվետվությունները Fluid Checkout-ին','These reports help us improve compatibility and support for your site and are sent weekly when enabled.' => 'Այս հաշվետվությունները մեզ օգնում են բարելավել ձեր կայքի համատեղելիությունն ու աջակցությունը և ուղարկվում են ամեն շաբաթ, երբ դրանք միացված են։','No customer, admin user, or any other sensitive data is included in the reports.' => 'Հաշվետվություններում չեն ներառվում հաճախորդների, ադմինիստրատորների կամ որևէ այլ զգայուն տվյալներ։','Basic environment info' => 'Հիմնական շրջակա միջավայրի մասին տեղեկություններ','WordPress, PHP, WooCommerce, theme, and plugin list data. Always included when reporting is enabled. Helps us understand the environment your site is running in.' => 'WordPress, PHP, WooCommerce, թեմաների և պլագինների ցանկի տվյալներ: Միշտ ներառվում են, երբ հաշվետվությունը միացված է: Օգնում է մեզ հասկանալ, թե ինչ միջավայրում է գործում ձեր կայքը:','Plugin settings' => 'Պլագինի կարգավորումներ','Sends Fluid Checkout plugin settings to help with support requests and helps us understand how you are using our plugins.' => 'Ուղարկում է Fluid Checkout պլագինի կարգավորումները՝ աջակցության հարցումներին օգնելու համար և օգնում է մեզ հասկանալ, թե ինչպես եք դուք օգտագործում մեր պլագինները։','Coming soon' => 'Շուտով','Sales metrics' => 'Վաճառքի չափանիշներ','Monthly order count and total sales for one year prior to installing Fluid Checkout up to today. Helps us understand if you are making more money with our plugins installed. No customer or user data is ever sent.' => 'Ամսական պատվերների քանակը և Fluid Checkout-ի տեղադրումից առաջ մեկ տարվա ընդհանուր վաճառքը մինչև այսօր։ Օգնում է մեզ հասկանալ, թե արդյոք դուք ավելի շատ գումար եք վաստակում մեր տեղադրված պլագիններով։ Հաճախորդի կամ օգտատիրոջ տվյալներ երբեք չեն ուղարկվում։','Utilities' => 'Կոմունալ ծառայություններ','Use <code>TomSelect</code> dropdown components instead of <code>select2</code>' => 'Օգտագործեք <code>TomSelect</code> իջնող ցանկի բաղադրիչները <code>select2</code> փոխարեն','TomSelect is a simpler dropdown selection component which is less prone to errors than Select2, while offering the same functionality.' => 'TomSelect-ը ավելի պարզ իջնող ընտրացանկի բաղադրիչ է, որն ավելի քիչ հակված է սխալների, քան Select2-ը, միաժամանակ առաջարկելով նույն ֆունկցիոնալությունը։','Sets the font size inside form fields to 16px on pages optimized by this plugin to avoid automatically zooming in when interacting with form fields on small devices.' => 'Այս հավելվածի կողմից օպտիմիզացված էջերում ձևաթղթերի դաշտերի ներսում տառատեսակի չափը սահմանում է 16px՝ փոքր սարքերում ձևաթղթերի դաշտերի հետ փոխազդելիս ավտոմատ մեծացումից խուսափելու համար։','Safari and other browsers might automatically zoom in on mobile devices to make the text easier to read when the font size is smaller than 16px.' => 'Safari-ն և այլ զննարկիչներ կարող են ավտոմատ կերպով մեծացնել տեքստը բջջային սարքերում՝ տեքստը ավելի հեշտ ընթեռնելի դարձնելու համար, երբ տառատեսակի չափը փոքր է 16 պիքսելից։','Enable script processing tracking on the browser console.' => 'Միացնել սկրիպտների մշակման հետևումը դիտարկիչի կոնսոլում:','Unminified assets' => 'Չմիացված ակտիվներ','Google Maps scripts' => 'Google Maps սկրիպտներ','Do not remove duplicate Google Maps scripts' => 'Մի՛ հեռացրեք կրկնօրինակ Google Maps սկրիպտները','When enabled, duplicate Google Maps scripts will NOT be removed which can cause errors and performance issues. Only use this option while troubleshooting.' => 'Երբ միացված է, կրկնօրինակ Google Maps սկրիպտները չեն հեռացվի, ինչը կարող է սխալներ և աշխատանքի հետ կապված խնդիրներ առաջացնել: Օգտագործեք այս տարբերակը միայն խնդիրների լուծման ժամանակ:','Widget areas' => 'Վիջեթների տարածքներ','Last step on mobile' => 'Վերջին քայլը բջջային հեռախոսում','Display widgets only at last step on mobile' => 'Ցուցադրել վիջեթները միայն բջջային հեռախոսի վերջին քայլում','Display checkout trust badge widgets only when viewing the last checkout step on mobile devices' => 'Վճարման վստահության նշանի վիջեթները ցուցադրել միայն բջջային սարքերում վճարման վերջին քայլը դիտելիս','Standard' => 'Ստանդարտ','VAT number field' => 'ԱԱՀ համարի դաշտ','Add a VAT number field to the billing form.' => 'Ավելացրեք ԱԱՀ համարի դաշտ հաշվարկային ձևին։','Field label' => 'Դաշտի պիտակ','Set the label of the VAT number field (ie. VAT number). On multi-language websites, it is better to leave this field empty and translate the original string.' => 'Սահմանեք ԱԱՀ համարի դաշտի պիտակը (օրինակ՝ ԱԱՀ համար): Բազմալեզու կայքերում ավելի լավ է այս դաշտը դատարկ թողնել և թարգմանել բնօրինակ տողը:','VAT Number' => 'ԱԱՀ համար','EU-VAT' => 'ԵՄ-ԱԱՀ','Enable the VAT number field to see more options' => 'Ակտիվացրեք ԱԱՀ համարի դաշտը՝ ավելի շատ տարբերակներ տեսնելու համար','VAT validation' => 'ԱԱՀ վավերացում','Validate VAT number field for EU-VAT during checkout' => 'Վճարման ընթացքում ստուգեք ԱԱՀ համարի դաշտը ԵՄ-ԱԱՀ-ի համար','Checks if the VAT Number provided is a valid VAT number registered on the European VIES Database (VAT Information Exchange System).' => 'Ստուգում է, թե արդյոք տրամադրված ԱԱՀ համարը վավեր ԱԱՀ համար է, որը գրանցված է եվրոպական VIES տվյալների բազայում (ԱԱՀ տեղեկատվության փոխանակման համակարգ):','Shop VAT number' => 'Խանութի ԱԱՀ համարանիշ','The shop\'s VAT number used for requesting EU-VAT validation, and printed on invoices. <br><strong>We strongly recommend adding your Shop VAT number</strong> as otherwise the VIES consultation results might not be valid for accounting purposes. <br>Ie.: <code>ATU99999999</code> or <code>EE999999999</code>.' => 'Խանութի ԱԱՀ համարը, որն օգտագործվում է ԵՄ-ԱԱՀ վավերացման համար և տպագրվում է հաշիվ-ապրանքագրերի վրա։<br> <strong>Մենք խստորեն խորհուրդ ենք տալիս ավելացնել ձեր խանութի ԱԱՀ համարը,</strong> քանի որ հակառակ դեպքում VIES խորհրդատվության արդյունքները կարող են անվավեր լինել հաշվապահական նպատակներով։<br> Այսինքն՝ <code>ATU99999999</code> կամ <code>EE999999999</code> :','Reverse charge' => 'Հակադարձ լիցքավորում','Apply reverse charge mechanism' => 'Կիրառեք հակադարձ լիցքավորման մեխանիզմը','Set tax rate to zero and display "Reverse charge" on invoices when the customer\'s VAT number is valid. A different "Reverse charge" text might be required depending on the store\'s country.' => 'Սահմանեք հարկային դրույքաչափը զրոյի և ցուցադրեք «Հակադարձ գանձում» գրառումը հաշիվ-ապրանքագրերի վրա, երբ հաճախորդի ԱԱՀ համարը վավեր է: Խանութի երկրից կախված՝ կարող է պահանջվել «Հակադարձ գանձում» գրառման այլ տարբերակ:','Same country' => 'Նույն երկիրը','Apply reverse charge mechanism for transactions in the shop country:' => 'Կիրառել հակադարձ գանձման մեխանիզմը խանութի երկրում գործարքների համար.','Enables applying reverse charge mechanism for transactions between companies in the same country as the shop.' => 'Հնարավորություն է տալիս կիրառել հակադարձ վճարման մեխանիզմ խանութի նույն երկրում գտնվող ընկերությունների միջև գործարքների համար։','Reverse charge exceptions' => 'Հակադարձ գանձման բացառություններ','Select additional countries to skip applying the reverse charge mechanism.' => 'Ընտրեք լրացուցիչ երկրներ՝ հակադարձ վճարի մեխանիզմի կիրառումը բաց թողնելու համար։','Taxes will be charged to orders from these countries even when a valid VAT number is provided.' => 'Այս երկրներից պատվերներից կգանձվեն հարկեր, նույնիսկ եթե տրամադրված է վավեր ԱԱՀ համար։','Reverse charge label on invoices' => 'Հակադարձ գանձման պիտակ հաշիվ-ապրանքագրերի վրա','Set the label of "reverse charge" on the checkout page and order details.' => 'Տեղադրեք «հակադարձ գանձում» պիտակը վճարման էջում և պատվերի մանրամասներում։','Reverse charge text on invoices' => 'Հակադարձ գանձման տեքստ հաշիվ-ապրանքագրերի վրա','Set the label of "reverse charge" text on invoices.' => 'Հաշիվ-ապրանքագրերի վրա դրեք «հակադարձ գանձում» տեքստը։','Tax to be paid on reverse charge basis' => 'Հակադարձ վճարման եղանակով վճարվող հարկ','Company name' => 'Ընկերության անվանումը','Autocomplete company name from VAT number' => 'Ընկերության անվան ավտոմատ լրացում՝ ԱԱՀ համարից','Fill in the billing company name based on the valid VAT number provided by the customer.' => 'Լրացրեք հաշիվ-ապրանքագրեր տրամադրող ընկերության անվանումը՝ հիմնվելով հաճախորդի կողմից տրամադրված վավեր ԱԱՀ համարի վրա։','Company name editing' => 'Ընկերության անվան խմբագրում','Allow editing of auto-filled company name' => 'Թույլատրել ավտոմատ լրացված ընկերության անվան խմբագրումը','When enabled, customers can change the company name associated with the provided VAT number.' => 'Երբ այս գործառույթը միացված է, հաճախորդները կարող են փոխել տրամադրված ԱԱՀ համարին կից ընկերության անվանումը։','EU-VAT for digital goods' => 'ԵՄ-ԱԱՀ թվային ապրանքների համար','From January 1st, 2015, modifications have been made to the EU VAT regulations concerning digital goods, impacting exclusively B2C transactions. The VAT on digital goods must be calculated based on the customer\'s location, and evidence of this needs to be collected (IP address and billing address).' => '2015 թվականի հունվարի 1-ից փոփոխություններ են կատարվել ԵՄ թվային ապրանքների վերաբերյալ ԱԱՀ կանոնակարգերում, որոնք վերաբերում են բացառապես B2C գործարքներին: Թվային ապրանքների ԱԱՀ-ն պետք է հաշվարկվի հաճախորդի գտնվելու վայրի հիման վրա, և անհրաժեշտ է հավաքել դրա ապացույցներ (IP հասցե և հաշվի հասցե):','Tax classes for digital goods' => 'Թվային ապրանքների հարկային դասեր','Select some tax classes' => 'Ընտրեք որոշ հարկային դասեր','Location evidence' => 'Տեղանքի ապացույցներ','Collect customer\'s location evidence' => 'Հավաքեք հաճախորդի գտնվելու վայրի ապացույցները','Saves the IP address and validate it against the customer\'s billing address. Customer\'s must confirm their billing address by checking a checkbox on the checkout page if the country from their billing address and IP do not match.' => 'Պահպանում է IP հասցեն և ստուգում այն հաճախորդի հաշվարկային հասցեի հետ։ Հաճախորդը պետք է հաստատի իր հաշվարկային հասցեն՝ նշելով վճարման էջում նշված վանդակը, եթե իր հաշվարկային հասցեում նշված երկիրը և IP հասցեն չեն համընկնում։','This option is managed in Fluid Checkout. <a href="%s">Change it in Customer accounts settings</a>.' => 'Այս տարբերակը կառավարվում է Fluid Checkout-ում: <a href="%s">Փոխեք այն Հաճախորդի հաշիվների կարգավորումներում</a> :','This option is managed in Fluid Checkout. Change it under Fluid Checkout > Customer accounts.' => 'Այս տարբերակը կառավարվում է Fluid Checkout-ում: Փոխեք այն Fluid Checkout &gt; Հաճախորդների հաշիվներ բաժնում:','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available in the <a href="%s">Fluid Checkout settings</a>.' => 'Այս տարբերակը կառավարվում է Fluid Checkout-ում: Fluid Checkout-ը ակտիվացնելիս առաքման նպատակակետը միշտ սահմանված է որպես «Հաճախորդի առաքման հասցեի լռելյայն կարգավորում»: Հաճախորդները դեռ կարող են տրամադրել տարբեր առաքման և հաշվարկային հասցեներ վճարման ընթացքում:<br><br> <a href="%s">Fluid Checkout կարգավորումներում</a> հասանելի է լռելյայն հաշվարկային հասցեն առաքման հասցեի հետ նույնը սահմանելու տարբերակ։','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available at WooCommerce > Settings > Fluid Checkout.' => 'Այս տարբերակը կառավարվում է Fluid Checkout-ում: Fluid Checkout-ը ակտիվացնելիս առաքման նպատակակետը միշտ սահմանված է որպես «Հաճախորդի առաքման հասցեի լռելյայն կարգավորում»: Հաճախորդները դեռ կարող են տրամադրել տարբեր առաքման և հաշվարկային հասցեներ վճարման ընթացքում:<br><br> WooCommerce &gt; Կարգավորումներ &gt; Հեղուկ վճարում կատարելիս կարող եք ընտրել, թե ինչպես կարգավորել լռելյայն վճարման հասցեն առաքման հասցեի հետ։','These settings have been moved to WP Admin > Fluid Checkout > Settings.' => 'Այս կարգավորումները տեղափոխվել են WP Admin &gt; Fluid Checkout &gt; Settings բաժին։','This WooCommerce Settings tab is deprecated and will be removed in Fluid Checkout 6.0.' => 'Այս WooCommerce Settings ներդիրը հնացած է և կհեռացվի Fluid Checkout 6.0-ում։','Go to settings page' => 'Անցնել կարգավորումների էջ','Hide this tab permanently' => 'Թաքցնել այս ներդիրը ընդմիշտ','Site report preview' => 'Կայքի հաշվետվության նախադիտում','This is the data that would be included in the next site environment report based on your current settings.' => 'Սրանք այն տվյալներն են, որոնք կներառվեն կայքի միջավայրի հաջորդ հաշվետվության մեջ՝ ձեր ընթացիկ կարգավորումների հիման վրա։','Loading report preview...' => 'Հաշվետվության նախադիտումը բեռնվում է...','Could not load the site report preview. Try again.' => 'Կայքի հաշվետվության նախադիտումը չհաջողվեց բեռնել։ Փորձեք կրկին։','Could not send the site report. Try again.' => 'Հնարավոր չէ ուղարկել կայքի մասին հաղորդումը։ Փորձեք կրկին։','Site report sent successfully.' => 'Կայքի հաշվետվությունը հաջողությամբ ուղարկվեց։','Enable and send now' => 'Միացնել և ուղարկել հիմա','Close' => 'Փակել','A site report request is already in progress. Try again in a moment.' => 'Կայքի մասին հաղորդման հարցումն արդեն ընթացքի մեջ է։ Փորձեք կրկին մի փոքր ուշ։','Site environment reporting is disabled.' => 'Կայքի միջավայրի հաշվետվությունը անջատված է։','No site report data is available to send.' => 'Կայքի հաշվետվության տվյալներ ուղարկելու համար հասանելի չեն։','This site domain cannot send environment reports (local or development domains are excluded).' => 'Այս կայքի տիրույթը չի կարող միջավայրի մասին հաշվետվություններ ուղարկել (տեղական կամ մշակման տիրույթները բացառված են):','A site report was sent recently. Try again later.' => 'Կայքի մասին հաղորդագրություն վերջերս ուղարկվել է։ Փորձեք կրկին ավելի ուշ։','The site report could not be sent. Try again later.' => 'Կայքի հաշվետվությունը չհաջողվեց ուղարկել: Փորձեք կրկին ավելի ուշ:','Site environment reporting is not available.' => 'Կայքի միջավայրի մասին հաշվետվությունը հասանելի չէ։','No site report data is available for the selected settings.' => 'Ընտրված կարգավորումների համար կայքի հաշվետվության տվյալներ հասանելի չեն։','You are not allowed to manage site reports.' => 'Դուք չունեք կայքի հաշվետվությունները կառավարելու թույլտվություն։','PRO feature' => 'PRO գործառույթ','Other plugins' => 'Այլ պլագիններ','Get only this add-on &mdash; %s' => 'Ստանալ միայն այս հավելումը — %s','Install add-on' => 'Տեղադրեք հավելումը','Upgrade to PRO &mdash; %s' => 'Թարմացնել PRO-ի — %s','<a target="_blank" href="%1$s">Get %2$s</a> to unlock these options.' => '<a target="_blank" href="%1$s">Ստացեք %2$s՝</a> այս տարբերակները բացելու համար։','Add-on' => 'Հավելում','View documentation' => 'Դիտել փաստաթղթերը','Requests require a logged-in WordPress user. Omit user_id to use the current user\'s data, or pass user_id to target another account when the caller can edit that user (edit_user capability). Unauthenticated requests return fc_api_forbidden. An invalid user_id returns fc_api_user_not_found.' => 'Հարցումները պահանջում են մուտք գործած WordPress օգտատեր։ Բաց թողեք user_id-ը՝ ընթացիկ օգտատիրոջ տվյալները օգտագործելու համար, կամ փոխանցեք user_id-ը՝ մեկ այլ հաշիվ թիրախավորելու համար, երբ զանգահարողը կարող է խմբագրել այդ օգտատիրոջը (edit_user հնարավորություն)։ Չհաստատված հարցումները վերադարձնում են fc_api_forbidden։ Անվավեր user_id-ն վերադարձնում է fc_api_user_not_found։','HTTP 200 with { "data": { ... } } when the handler returns a payload.' => 'HTTP 200-ը { &quot;data&quot;: { ... } }-ով, երբ մշակիչը վերադարձնում է օգտակար բեռ։','HTTP 200 with { "success": true } when there is no payload (for example DELETE).' => 'HTTP 200՝ { &quot;success&quot;: true } պարամետրով, երբ բեռ չկա (օրինակ՝ DELETE):','Failures return WordPress REST error JSON from WP_Error (code, message, data.status). Wire codes use the fc_api_* prefix.' => 'Ձախողումները WP_Error-ից (code, message, data.status) վերադարձնում են WordPress REST սխալի JSON ֆայլը։ Էլեկտրոնային կոդերը օգտագործում են fc_api_* նախածանցը։','Forbidden access.' => 'Արգելված մուտք։','Target user was not found.' => 'Նպատակային օգտատերը չի գտնվել։','This feature is not available.' => 'Այս գործառույթը հասանելի չէ։','A required address field is missing.' => 'Պարտադիր հասցեի դաշտը բացակայում է։','Postcode or ZIP is invalid.' => 'Փոստային ինդեքսը կամ փոստային ինդեքսը անվավեր է։','Phone number is invalid.' => 'Հեռախոսահամարը անվավեր է։','State or county is invalid.' => 'Նահանգը կամ շրջանը անվավեր է։','Country is invalid or has no address fields.' => 'Երկիրը անվավեր է կամ հասցեի դաշտեր չունի։','The request could not be processed.' => 'Հարցումը չհաջողվեց մշակել։','Back to previous step' => 'Վերադառնալ նախորդ քայլին','Skip to settings' => 'Անցնել կարգավորումներին','Start over and return to the first guided setup step' => 'Սկսեք նորից և վերադարձեք առաջին ուղեցույցով կարգավորման քայլին','Start over' => 'Սկսել նորից','Please complete all sub-steps before continuing.' => 'Խնդրում ենք շարունակելուց առաջ ավարտել բոլոր ենթաքայլերը։','Expand' => 'Ընդարձակել','Collapse' => 'Ծալել','Skip' => 'Բաց թողնել','Mark as complete' => 'Նշել որպես ավարտված','Mark as incomplete' => 'Նշել որպես անավարտ','View full-size image: %s' => 'Դիտել լրիվ չափի պատկերը՝ %s','Full-size setup guide image' => 'Լրիվ չափի կարգավորման ուղեցույցի պատկեր','Close image' => 'Փակել պատկերը','Fluid Checkout Guided Setup' => 'Հեղուկի ստուգման ուղղորդվող կարգավորում','Welcome' => 'Բարի գալուստ','Explore your checkout' => 'Ուսումնասիրեք ձեր վճարման ձևը','All set' => 'Ամեն ինչ պատրաստ է','You do not have permission to access this page.' => 'Դուք չունեք այս էջին մուտք գործելու թույլտվություն։','Go to step %1$d: %2$s' => 'Անցնել %1$d քայլին՝ %2$s','This guided setup helps you get familiar with Fluid Checkout. The steps below are placeholders for now.' => 'Այս ուղղորդվող կարգավորումը կօգնի ձեզ ծանոթանալ Fluid Checkout-ի հետ: Ստորև նշված քայլերը առայժմ փոխարինող են:','Continue to the next step when you are ready.' => 'Շարունակեք հաջորդ քայլին, երբ պատրաստ լինեք։','Open your store checkout to see Fluid Checkout in action.' => 'Բացեք ձեր խանութի դրամարկղը՝ Fluid Checkout-ը գործողության մեջ տեսնելու համար։','View checkout page' => 'Դիտել վճարման էջը','You can return to Fluid Checkout settings to continue configuring your store.' => 'Դուք կարող եք վերադառնալ Fluid Checkout-ի կարգավորումներին՝ ձեր խանութի կարգավորումը շարունակելու համար։','Review checkout and cart settings' => 'Վերանայեք վճարման և զամբյուղի կարգավորումները','Explore add-ons from the dashboard' => 'Ուսումնասիրեք հավելումները վահանակից','Finish & go to settings' => 'Ավարտեք և անցեք կարգավորումներ','Update the billing phone field visibility option from the legacy value to match WooCommerce conventions.' => 'Թարմացրեք վճարման հեռախոսահամարի դաշտի տեսանելիության տարբերակը ժառանգական արժեքից՝ WooCommerce կոնվենցիաներին համապատասխանեցնելու համար։','Update the shipping phone field visibility option from the legacy value to match WooCommerce conventions.' => 'Թարմացրեք առաքման հեռախոսահամարի դաշտի տեսանելիության տարբերակը ժառանգական արժեքից՝ WooCommerce կոնվենցիաներին համապատասխանեցնելու համար։','Copy the order summary background color setting to the new Split design secondary column background color option.' => 'Պատճենեք պատվերի ամփոփման ֆոնի գույնի կարգավորումը «Բաժանել դիզայնի երկրորդական սյունակի ֆոնի գույնի» նոր տարբերակին։','The enhanced select fields feature is always disabled when using the Biteship plugin.' => 'Biteship հավելվածն օգտագործելիս բարելավված ընտրության դաշտերի գործառույթը միշտ անջատված է։','The place order position is always set to "Below the order summary" when using German Market. That plugin requires the place order button and legal checkboxes to be displayed below the order summary.' => 'Գերմանական շուկան օգտագործելիս պատվերի տեղադրման դիրքը միշտ սահմանված է «Պատվերի ամփոփումից ներքև»։ Այդ հավելվածը պահանջում է, որ պատվերի տեղադրման կոճակը և օրինական նշատուփերը ցուցադրվեն պատվերի ամփոփումից ներքև։','The place order position is always set to "Below the order summary" when using Germanized for WooCommerce. That plugin requires the place order button and legal checkboxes to be displayed below the order summary.' => 'WooCommerce-ի համար Germanized-ն օգտագործելիս պատվերի տեղադրման դիրքը միշտ սահմանվում է «Պատվերի ամփոփագրի տակ»։ Այդ հավելվածը պահանջում է, որ պատվերի տեղադրման կոճակը և օրինական նշատուփերը ցուցադրվեն պատվերի ամփոփագրի տակ։','Edit pickup locations' => 'Խմբագրել վերցման վայրերը','Use local pickup label from WooCommerce settings' => 'Օգտագործեք WooCommerce-ի կարգավորումներից տեղական վերցման պիտակը','When enabled, the pickup option label on checkout matches the title from WooCommerce pickup location settings. When disabled, the label uses the translatable "Local pickup" text from Fluid Checkout.' => 'Երբ միացված է, վճարման ժամանակ վերցման տարբերակի պիտակը համընկնում է WooCommerce վերցման վայրի կարգավորումների վերնագրի հետ: Երբ անջատված է, պիտակը օգտագործում է Fluid Checkout-ից թարգմանելի «Տեղական վերցում» տեքստը:','Button label for applying coupon codesApply' => 'Դիմել','Checkout step titleContact' => 'Կապ','Checkout step titleShipping' => 'Առաքում','Checkout step titleBilling' => 'Բիլինգ','Checkout step titlePayment' => 'Վճարում','Checkout substep change link labelChange' => 'Փոփոխություն','Checkout substep save link labelSave changes' => 'Պահպանել փոփոխությունները','Substep review textNone.' => 'Ոչ մեկը:','Substep review field format%1$s' => '%1$s','Substep review field format: with label%2$s: %1$s' => '%2$s՝ %1$s','Image uploader.No image selected.' => 'Պատկեր ընտրված չէ:','Settings sectionCart' => 'Սայլակ','Settings sectionOrder pay' => 'Պատվիրեք վճարում','Settings sectionThank you' => 'Շնորհակալություն','Settings section titleIntegrations' => 'Ինտեգրումներ','Settings section titleLicense keys' => 'Լիցենզիայի բանալիներ','Captcha positionBefore place order section' => 'Նախքան պատվերի տեղադրումը բաժինը','Captcha positionBefore place order button' => 'Նախքան պատվերի տեղադրման կոճակը','No shipping method chosen label for the order summary--' => '--','Close button aria-labelClose' => 'Փակել','Log in link label at checkout contact stepLog in' => 'Մուտք գործեք','Log in separator label at for when guest checkout is disabledOr continue below' => 'Կամ շարունակեք ստորև','Log in separator label at for when guest checkout is disabledOr continue as a guest' => 'Կամ շարունակեք որպես հյուր','Clear image selection on admin pages.Remove image' => 'Հեռացնել պատկերը','shipping packagesShipping %d' => 'Առաքում %d','shipping packagesShipping' => 'Առաքում','Used as fallback for "Proceed to next step" button labelnext step' => 'հաջորդ քայլը','Substep review checkbox valueYes' => 'Այո','Substep review checkbox line%1$s: %2$s' => '%1$s: %2$s','Dummy customer first name in the admin previewJohn' => 'Ջոն','Dummy customer last name in the admin previewDoe' => 'Էգ','Dummy customer company in the admin previewExample Company' => 'Օրինակելի ընկերություն','Dummy customer street address in the admin preview123 Main Street' => 'Գլխավոր փողոց 123','Dummy customer city in the admin previewAnytown' => 'Էյնթաուն','Dummy order notes in the admin previewPlease leave the package at the front door.' => 'Խնդրում ենք փաթեթը թողնել դռան մոտ։','Dummy product name in the admin previewBeanie' => 'Բենի','Dummy product name in the admin previewCap' => 'Գլխարկ','Dummy product name in the admin previewT-Shirt' => 'Մարզաշապիկ','Dummy order update in the admin previewWe received your order and will send you an update when it ships.' => 'Մենք ստացանք Ձեր պատվերը և կուղարկենք Ձեզ թարմացում, երբ այն առաքվի։','Dummy download in the admin previewUser guide' => 'Օգտագործողի ուղեցույց','Google Places API versionsPlaces API (New)' => 'Վայրերի API (Նոր)','Google Places API versionsPlaces API (Legacy)' => 'Վայրերի API (Legacy)','Brasil API versionsVersion 1' => 'Տարբերակ 1','Brasil API versionsVersion 2' => 'Տարբերակ 2','Delayed account creation benefits placeholder text✔ Checkout faster next time
✔ Manage your payment preferences
✔ View order status and history' => '✔ Հաջորդ անգամ ավելի արագ վճարում կատարեք ✔ Կառավարեք ձեր վճարման նախընտրությունները ✔ Դիտեք պատվերի կարգավիճակը և պատմությունը','VAT number field visibilityHidden' => 'Թաքնված','VAT number field visibilityOptional' => 'Ըստ ցանկության','VAT number field visibilityRequired' => 'Պարտադիր','Delivery typeShipping to address' => 'Առաքում հասցեով','Delivery typeLocal pickup' => 'Տեղական վերցման ծառայություն',] ];